/*
 * Flow types the flow key may point to.
 */
#define FLOW_PERSISTED          0x20
#define FLOW_CLIENTSIDE         0x40
#define FLOW_SERVERSIDE         0x80

#define FLOWTYPE_PROXY          0x00
#define FLOWTYPE_PROXYCLIENT    (FLOWTYPE_PROXY|FLOW_CLIENTSIDE)
                                /* Client side of proxy             */
#define FLOWTYPE_PROXYSERVER    (FLOWTYPE_PROXY|FLOW_SERVERSIDE)
                                /* Server side of proxy             */
#define FLOWTYPE_BIGIP          0x01
#define FLOWTYPE_BIGIPCLIENT    (FLOWTYPE_BIGIP|FLOW_CLIENTSIDE)
                                /* Client side of BIG-IP conn       */
#define FLOWTYPE_BIGIPSERVER    (FLOWTYPE_BIGIP|FLOW_SERVERSIDE)
                                /* Server side of BIG-IP conn       */
#define FLOWTYPE_SELF           0x02
#define FLOWTYPE_SELFCLIENT     (FLOWTYPE_SELF|FLOW_CLIENTSIDE)
                                /* Client side of self traffic      */
#define FLOWTYPE_SELFSERVER     (FLOWTYPE_SELF|FLOW_SERVERSIDE)
                                /* Server side of self traffic      */
#define FLOWTYPE_RELATED        0x03
#define FLOWTYPE_RELATEDCLIENT  (FLOWTYPE_RELATED|FLOW_CLIENTSIDE)
                                /* Related connection               */
#define FLOWTYPE_RELATEDSERVER  (FLOWTYPE_RELATED|FLOW_SERVERSIDE)
                                /* Related connection               */
#define FLOWTYPE_L2             0x04
#define FLOWTYPE_L2CLIENT       (FLOWTYPE_L2|FLOW_CLIENTSIDE)
                                /* Related connection               */
#define FLOWTYPE_L2SERVER       (FLOWTYPE_L2|FLOW_SERVERSIDE)
                                /* Related connection               */
#define FLOWTYPE_CLONE          0x05
#define FLOWTYPE_CLONESERVER    (FLOWTYPE_CLONE|FLOW_SERVERSIDE)
                                /* Clone flows are server side      */
#define FLOWTYPE_TEMP           0x06
#define FLOWTYPE_TEMPCLIENT    (FLOWTYPE_TEMP|FLOW_CLIENTSIDE)
#define FLOWTYPE_TEMPSERVER    (FLOWTYPE_TEMP|FLOW_SERVERSIDE)
                                /* Temporary flows */
#define FLOWTYPE_INTERNAL       0x07
#define FLOWTYPE_INTERNALCLIENT (FLOWTYPE_INTERNAL|FLOW_CLIENTSIDE)
                                /* Internal flows are server side   */
#define FLOWTYPE_INTERNALSERVER (FLOWTYPE_INTERNAL|FLOW_SERVERSIDE)
                                /* Internal flows are server side   */
#define FLOWTYPE_FWD            0x08
#define FLOWTYPE_FWDCLIENT      (FLOWTYPE_FWD|FLOW_CLIENTSIDE)
                                /* client side forwarded flow       */
#define FLOWTYPE_FWDSERVER      (FLOWTYPE_FWD|FLOW_SERVERSIDE)
                                /* server side forwarded flow       */
#define FLOWTYPE_SERVICE        0x09
#define FLOWTYPE_SERVICECLIENT  (FLOWTYPE_SERVICE|FLOW_CLIENTSIDE)
                                /* client side service flow       */
#define FLOWTYPE_SERVICESERVER  (FLOWTYPE_SERVICE|FLOW_SERVERSIDE)
                                /* server side service flow       */

#define FLOWTYPE_FFWD            0x0a
#define FLOWTYPE_FFWDCLIENT      (FLOWTYPE_FFWD|FLOW_CLIENTSIDE)
                                /* client side fast forwarded flow */
#define FLOWTYPE_FFWDSERVER      (FLOWTYPE_FFWD|FLOW_SERVERSIDE)
                                /* server side fast forwarded flow */

#define FLOWTYPE_SHAPER          0x0b
#define FLOWTYPE_STATIC          0x0f

#define IS_CLIENTSIDE(a) ((((a)->flow_type) & FLOW_CLIENTSIDE) != 0)
#define IS_SERVERSIDE(a) ((((a)->flow_type) & FLOW_SERVERSIDE) != 0)
#define FLOW_IS_PERSISTED(a) ((((a)->flow_type) & FLOW_PERSISTED) != 0)
#define FLOW_SET_PERSISTED(a, b) (a)->flow_type |= (b) ? FLOW_PERSISTED : 0;
#define FLOW_TYPE(a)     (((a)->flow_type) & 0x0F)
#define FLOW_MAKE_TYPE(t, cs) \
    (((t) & 0x0F) | ((cs) & (FLOW_CLIENTSIDE | FLOW_SERVERSIDE)))
#define FLOW_SIDE(a) IS_CLIENTSIDE(a) ? "clientside" : "serverside"

#define CONNFLOW_NODE(c) ((c)->top_node)

#define FWD_FLOW_OWNER_ID(addr, port) (ntohl(XOR_128_32(&(addr))) ^ (port))

#define FLOW_KEY_L3_VALID   0x01

#define pkt_flow_key_set_bit(key, f) ( \
        (key)->pde_idx |= (f))

#define pkt_flow_key_clear_bit(key, f) ( \
        (key)->pde_idx &= ~(f))

/* TODO: remove this hack as there are still bits available in CONNFLOW_FLAGS */
#define pkt_flow_key_test_bit(key, f) ( \
        ((key)->pde_idx & (f)) != 0)

struct flow_key {
    /*
     * Primary match fields.  These must match the first data fields
     * in struct connflow, flowfwd and uflow_key.
     */
    ip_addr_t        remote_addr;
    ip_addr_t        local_addr;
    inet_port_t      remote_port;
    inet_port_t      local_port;
    UINT8            ipproto;
    UINT8            flow_type;         /* Unused for matching              */

    /*
     * Secondary match fields.  These are only checked if the fields
     * above match.
     */
    UINT16           rtdom_id;          /* routing domain                   */
    union {
        UINT64       flags;
        struct {
            UINT64   flags62 : 62;      /* secondary match field            */
            UINT64   pde_idx : 2;       /* pde_idx from port_find   */
        };
    };
    struct ifc      *ifc;               /* related interface object */
};

/* This struct must match the fields in struct flow_key */
struct uflow_key {
    union {
        /* struct flow_key expanded inline to allow easy access to its fields */
        struct {
            ip_addr_t        remote_addr;
            ip_addr_t        local_addr;
            inet_port_t      remote_port;
            inet_port_t      local_port;
            UINT8            ipproto;
            UINT8            flow_type;         /* Unused for matching */

            /*
             * Secondary match fields.  These are only checked if the fields
             * above match.
             */
            UINT16           rtdom_id;          /* routing domain */
            union {
                UINT64       flags;
                struct {
                    UINT64   flags62 : 62;      /* secondary match field */
                    UINT64   pde_idx : 2;       /* pde_idx from port_find */
                };
            };
            struct ifc      *ifc;               /* related interface object */
        };
        struct flow_key     flow_key;
    };

    /* Extra field */
    UINT64           stream_id;
};


typedef struct {
    UINT32           pkts_in;           /* Inbound packet count     */
    UINT32           pkts_out;          /* Outbound packet count    */
    UINT64           bytes_in;          /* Inbound byte count       */
    UINT64           bytes_out;         /* Outbound byte count      */
} connflow_stat_t;

/* The actual connection flow entry */

CACHE_ALIGN_BEGIN                       /* Comment */
struct connflow {
    ip_addr_t        remote_addr;       /* Remote address           */
    ip_addr_t        local_addr;        /* Local address            */
    inet_port_t      remote_port;       /* Remote L4 port           */
    inet_port_t      local_port;        /* Local L4 port            */
    UINT8            ipproto;           /* IP protocol              */
    /* End of primary match fields. */

    UINT8            flow_type;         /* Type of flow             */
    UINT16           rtdom_id;          /* Routing domain           */
    UINT64           flags;             /* Connection flags         */
    struct ifc      *ifc;               /* Related interface object */
    LIST_ENTRY(connflow) cf_next;       /* Next connflow in bucket  */
/* --- x86_64 cacheline 1 boundary (64 bytes) was 8 bytes ago --- */
    union uflow      *peer;             /* Peer flow                */
    struct hudnode   *bottom_node;      /* bottom of filter chain   */
    struct hudnode   *top_node;         /* top of filter chain      */
    struct nexthop   *nexthop;          /* Cached nexthop           */
    UINT64           tmmrule_events;    /* TMM Rule events Bloom Filter */
    struct tclrule_pcb *tclpcb;         /* TCL connection context   */

    union {
        UINT16          mss;            /* MSS                      */
        struct cmp_node cmp_dest;       /* CMP cluster destination  */
    };
    UINT8            priority:4;        /* transmit packet priority */
    UINT8            trunk_idx:3;       /* cached index of trunk    */
    UINT8            ha_wait_fb_ack:1;  /* need reply for cmp failback*/
    UINT8            ha_unit:HA_UNIT_BITS;
    UINT8            ha_waiting_ack:1;  /* need reply from standby  */
    UINT32           tstamp;            /* last time flow used      */

/* --- x86_64 cacheline 2 boundary (128 bytes) --- */
    connflow_stat_t  stats;             /* flow statistics          */
    UINT16           egress_mtu;        /* Egress MTU               */
    UINT16           ingress_mtu;       /* Ingress MTU              */
    UINT16           ref;               /* Reference count          */
    UINT8            ingress_link_qos:3;/* Initial link QoS         */
    UINT8            egress_link_qos:3; /* Outbound link_qos        */
    UINT8            link_qos_set:1;    /* Link QOS set             */
    UINT8            ip_tos_set:1;      /* IP TOS set               */
    UINT8            ingress_ip_tos;    /* Initial IP TOS           */
    UINT8            egress_ip_tos;     /* Outbound IP TOS          */
    UINT8            ingress_ip_ttl;    /* Initial IP TTL           */
    UINT8            egress_ip_ttl;     /* Egress IP TTL            */
    UINT8            ha_gen_id:HA_GEN_ID_BITS;
    UINT8            ip_ttl_set:1;      /* Egress IP TTL set        */
    UINT8            ingress_df_flag:1; /* DF flag bit              */
    UINT8            egress_df_flag:1;  /* DF flag bit              */
    UINT8            ha_mirror_failed:1;/* L7 mirroring failed      */
    UINT32           idle_timeout;      /* idle timeout in seconds  */
    union {
        struct bwc_shaper *bwc_shaper;  /* Per-flow BWC context.    */
        struct rateshaper *rateshaper;  /* Per-flow rate-shaping    */
        UINT64             owner_id;    /*
                                         * This is set only for
                                         * forwarding flows, to tell
                                         * whether the flow can be
                                         * reused
                                         */
    };
    struct rt_entry  *rt_entry;         /* Cached route             */
    struct poolmbr   *pmbr;             /* LB pool member chosen    */
/* --- x86_64 cacheline 3 boundary (192 bytes) --- */
    struct listener_key  *listener_key; /* associated listener key  */
    struct sa_entry      *sa_entry;         /* source address translation pick */
    union {                             /*                          */
        struct connflow     *parent_cf;            /* Related/ephemeral parent */
        struct listener_key *other_listener_key; /* other listenerkey (VIP+SNAT)*/
        struct tmm_traffic_stat *tc_traffic_stat;   /*
                                                     * traffic stat for
                                                     * transpot-config
                                                     */
    };
    connflow_stat_t  last_accum_stats;  /* stats at last flow_counts_accum() */
    struct tm_opaque_table *tm_opaque_table; /* Opaque context data */
    clock_tick_t     start_tick;        /* Flow start time in ticks */
/* --- x86_64 cacheline 4 boundary (256 bytes) --- */
#if (FLOW_TRACE >= 1)
    const char      *trace_txt[1 << FLOW_TRACE]; /* Trace messages. */
    unsigned        trace_idx : FLOW_TRACE;      /* Current index. */
#else
                                        /* End                      */
#endif
} CACHE_ALIGN_END;

/* Stream analogue of a connflow */
struct streamflow {
    UINT32 ref;

    /*
     * Currently (this does not appear to be guaranteed), this
     * field has the same offset from the beginning of an unprocessed
     * uflow pointer in both the connflow and stream flow structures.
     *
     * IOW: &uf->sf.flow_type == &uf->cf.flow_type
     */
    UINT8 flow_type;

    /*
     * This pad array is not waste.  It pushes the following fields
     * down in order to facilitate the processing of a uflow
     * pointer into a connflow pointer, one that can then be used to
     * access SOME of the same fields in either type.
     *
     * More on this below.
     */
    UINT8 pad[11]; /* Unused. */

    UINT64 stream_id;
    struct tm_opaque_table *tm_opaque_table;
    UINT64 flags;

    /* 
     * After the uflow pointer is processed through the
     * uflow_offset_connflow() function, the resulting
     * struct connflow pointer can be used to access five of
     * the six following fields regardless of underlying
     * real type of the data.
     *
     * Do NOT use the processed connflow pointer to access any other
     * fields in the connflow!  DO use the macros created by
     * expanding the UFLOW_FIELD_ALIGNED macro (which calls the 
     * uflow_offset_connflow function for you).
     */
    union uflow *peer;
    struct hudnode *bottom_node;
    struct hudnode *top_node;

    /*
     * This is an exception, as it has a different type than
     * the field in the connflow.
     */
    struct connflow *cf;

    UINT64 tmmrule_events;
    struct tclrule_pcb *tclpcb;
};

/*
 * This is a helper type to have a type-safe way of representing
 * a flow that is either a connflow or a streamflow.
 *
 * Streamflows are stored as "odd", and connflows "even" addresses
 * of the uflow pointer.
 *
 * Note: The underlying connflow and streamflow structs are always
 * pointer-aligned by the ABI.  The 33-byte pad here causes the
 * uflow pointer to be mis-aligned for streamflows.
 */
union uflow {
    struct {
        /*
         * This offset is odd, and in the case of a
         * streamflow, the pad is NOT allocated memory.  Do
         * not attempt to read or write the pad storage,
         * as in reality it is most likely storage occupied
         * by the dynamic memory management system block header,
         * or the storage of some other object.
         *
         * IOW, a streamflow pointer is converted into uflow
         * through the uflow_fromstreamflow function, using
         * the equivalent of:
         *
         * (union uflow *) ((uintptr_t) sf - 33)
         *
         * See: uflow_fromstreamflow()
         *
         * The value of 33 was chosen in order to facilitate
         * the ability to use a uflow pointer (one modified by
         * another function that peforms a computed conditional
         * operation based on whether or not the uflow address value
         * is odd or even) to be used to access a small subset of
         * the same fields of either a connflow or a streamflow.
         *
         * Computed conditional operation:
         *
         * addr = (uintptr_t) uf
         * cf   = (struct connflow *) (addr + (addr & 1))
         */
        BYTE pad[33];
        struct streamflow sf;
    } __PACKED;
    struct connflow cf;
};

/* connflow needs repacking if these change */
STATIC_ASSERT(HA_UNIT_BITS == 7);
STATIC_ASSERT(HA_GEN_ID_BITS == 3);

#define CONNFLOW_ALIGN_BITS     6
#define CONNFLOW_ALIGNMENT      (1 << CONNFLOW_ALIGN_BITS)
#define CONNFLOW_ALIGN_MASK     (CONNFLOW_ALIGNMENT - 1)
/*
 * Maximum "safe" reference count. This is not strictly enforced otherwise
 * it would be necessary to check for this limit on every flow_addref().
 * Instead check only in functions which are likly to add a large number of
 * references to the connflow. Currently this is only the code in rateshaper.
 */
#define CONNFLOW_MAX_SAFE_REFCNT    65000

#if defined(__GNUC__) && defined(__SSE2__)
/*
 * SSE2 implementation of flow match which is significantly faster.
 * the last 5 bytes is masked out and 64 bit comparison is done.
 */
#define CONNFLOW_KEY_MISMATCH(cf, key) ({                       \
    register unsigned long result;                              \
    __asm__ __volatile__ (                                      \
        "movdqu %1, %%xmm1\t\n\t"                               \
        "movdqu %2, %%xmm0\t\n\t"                               \
        "pcmpeqd %%xmm1, %%xmm0\t\n\t"                          \
        "pmovmskb %%xmm0, %%rax\t\n\t"                          \
        "movdqu %3, %%xmm1\t\n\t"                               \
        "movdqu %4, %%xmm0\t\n\t"                               \
        "pcmpeqd %%xmm1, %%xmm0\t\n\t"                          \
        "pmovmskb %%xmm0, %0\t\n\t"                             \
        "and %%rax, %0\t\n\t"                                   \
        "xor $0xFFFF, %0\t\n\t"                                 \
        "xor %5, %6\t\n\t"                                      \
        "or %6, %0\t\n\t"                                       \
        :"=&r" (result)                                         \
        :"m" (*(&(cf)->remote_addr)), "m" (*(&(key)->remote_addr)), \
         "m" (*(&(cf)->local_addr)), "m" (*(&(key)->local_addr)),   \
         "r" ((*(UINT64 *)&(cf)->remote_port) & 0xFFFFFFFFFF),  \
         "r" ((*(UINT64 *)&(key)->remote_port) & 0xFFFFFFFFFF)  \
        :"xmm0", "xmm1", "rax", "memory"                        \
    );                                                          \
    result;                                                     \
})
#else
/*
 * Returns 0 if the key matches the connflow, non-zero if it does not.
 * This is here because it is heavily dependent on field size and order,
 * and must be updated if the primary match fields change.
 *
 * The address fields are compared separately, rather than using bcmp()
 * to compare all the fields at once, because an ip_addr_t is the
 * largest data size that bcmp() will compare inline; anything larger
 * requires a function call.
 */
#define CONNFLOW_KEY_MISMATCH(cf, key) (                           \
        inet_addr_not_equal((key)->remote_addr, (cf)->remote_addr, \
                CONNFLOW_ADDR_SIZE(cf)) |                          \
        inet_addr_not_equal((key)->local_addr, (cf)->local_addr,   \
                CONNFLOW_ADDR_SIZE(cf)) |                          \
        bcmp(&(cf)->remote_port, &(key)->remote_port,              \
                (offsetof(struct flow_key, ipproto) -              \
                 offsetof(struct flow_key, remote_port) + sizeof(UINT8))))
#endif /* __SSE2__ */

#define CONNFLOW_FLOW_KEY(cf) ((struct flow_key *)&((cf)->remote_addr))

#define CONNFLOW_TOP_CTX(cf)                                                \
    (((cf)->top_node == NULL) ? NULL : HUDNODE_CTX((cf)->top_node))
#define CONNFLOW_BOTTOM_CTX(cf)                                             \
    (((cf)->bottom_node == NULL) ?  NULL : HUDNODE_CTX((cf)->bottom_node))
#define CONNFLOW_FILTER(cf)                                                 \
    (((cf)->bottom_node == NULL) ? NULL : HUDNODE_FILTER((cf)->bottom_node))
#define CONNFLOW_PROXY(cf)                                                  \
    (((cf)->bottom_node == NULL) ? NULL : HUDNODE_PROXY((cf)->bottom_node))

