/*
 * Generic flow processing.
 * A flow is either a connflow or a streamflow.
 * The low bit of the address of the pointer is used as a tag.
 */
static inline BOOL
uflow_isstreamflow(const union uflow *uf)
{
    return (INT(uf) & 1) != 0;
}

static inline BOOL
uflow_isconnflow(const union uflow *uf)
{
    return !uflow_isstreamflow(uf);
}

static inline struct connflow *
uflow_connflow(union uflow *uf)
{
    return uflow_isconnflow(uf) ? &uf->cf : NULL;
}

/* GCC >= 9 doesn't like pointers into packed structs. Allow for uf */
#if defined(__GNUC__) && (__GNUC__ >= 9)
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Waddress-of-packed-member"
#endif

static inline struct streamflow *
uflow_streamflow(union uflow *uf)
{
    return uflow_isstreamflow(uf) ? &uf->sf : NULL;
}
static inline union uflow *
uflow_fromconnflow(struct connflow *cf)
{
    DBG_ASSERT("cf alignment", (INT(cf) & 1) == 0);
    return containerof(union uflow, cf, cf);
}

static inline union uflow *
uflow_fromstreamflow(struct streamflow *sf)
{
    DBG_ASSERT("sf alignment", (INT(sf) & 1) == 0);
    return containerof(union uflow, sf, sf);
}

/* Helper type for the uflow_expand() function */
enum uflow_type {
    uflow_type_connflow,
    uflow_type_streamflow,
};

/*
 * Helper function to switch based on union tag type.
 * This is expected to be used in an if statement.
 * Note that the "wrong" input is deliberately not initialized.
 * Thus the compiler will most likely warn about incorrectly
 * using the wrong type of flow.
 */
static inline enum uflow_type
uflow_expand(union uflow *uf, struct connflow **cf, struct streamflow **sf)
{
    if (uflow_isconnflow(uf)) {
        *cf = &uf->cf;
        return uflow_type_connflow;
    } else {
        *sf = &uf->sf;
        return uflow_type_streamflow;
    }
}

/* Similarly as above, but for const */
static inline enum uflow_type
const_uflow_expand(const union uflow *uf, const struct connflow **cf,
        const struct streamflow **sf)
{
    if (uflow_isconnflow(uf)) {
        *cf = &uf->cf;
        return uflow_type_connflow;
    } else {
        *sf = &uf->sf;
        return uflow_type_streamflow;
    }
}

#if defined(__GNUC__) && (__GNUC__ >= 9)
#pragma GCC diagnostic pop /* END -Waddress-of-packed-member ignore */
#endif

/*
 * A stream has an associated connflow for the connection.
 * Return that connflow.  (Or if we are already a connflow
 * return ourselves.)
 *
 * This differs from uflow_connflow() which will return NULL
 * if the flow is a stream.
 */
static inline struct connflow *
uflow_get_connflow(union uflow *uf)
{
    struct connflow *cf = NULL;
    struct streamflow *sf = NULL;
    return (uflow_expand(uf, &cf, &sf) == uflow_type_connflow) ?
        cf : sf->cf;
}

static inline struct hudnode *
uflow_get_node(union uflow *uf, struct hudnode *node)
{
    extern struct hudnode *streamnode_node(struct hudnode *node);
    struct connflow *cf;
    struct streamflow *sf;
    /* HUDNODE_NODE(), open-coded so hudfilter.h isn't required */
    return (uflow_expand(uf, &cf, &sf) == uflow_type_connflow) ?
        node : streamnode_node(node);
}

static inline struct listener_key *
uflow_get_listener_key(union uflow *uf)
{
    return uflow_get_connflow(uf)->listener_key;
}

static inline struct connflow *
flow_peer(const struct connflow *cf)
{
    return uflow_get_connflow(cf->peer);
}

static inline struct connflow *
uflow_offset_connflow(const union uflow *uf)
{
    /*
     * Return this pointer if the flow is a connflow.
     * If it is a streamflow, offset by a byte and return that.
     *
     * This is helpful to make fast accessor functions that
     * require the alignment of fields such that
     * offset(cf->field) = offset(sf->field) + sizeof(uf->pad) - 1
     */
    return (void *)&((UINT8 *)uf)[uflow_isstreamflow(uf)];
}

/*
 * Access a field F of the given subset (see notes above, and below
 * where this macro is expanded) in what is actually either a connflow
 * or streamflow.
 */
#define UFLOW_FIELD_ALIGNED(F, T)                                   \
static inline T uflow_##F(const union uflow *uf)                    \
{                                                                   \
    return uflow_offset_connflow(uf)->F;                            \
}                                                                   \
                                                                    \
static inline T * uflow_ptr_##F(union uflow *uf)                    \
{                                                                   \
    return &uflow_offset_connflow(uf)->F;                           \
}

/* Access a field F in a connflow or streamflow of a given type T */
#define UFLOW_FIELD(F, T)                                               \
static inline T uflow_##F(const union uflow *uf)                        \
{                                                                       \
    const struct connflow *cf = NULL;                                   \
    const struct streamflow *sf = NULL;                                 \
    return (const_uflow_expand(uf, &cf, &sf) == uflow_type_connflow) ?  \
        cf->F : sf->F;                                                  \
}                                                                       \
static inline T *uflow_ptr_##F(union uflow *uf)                         \
{                                                                       \
    struct connflow *cf = NULL;                                         \
    struct streamflow *sf = NULL;                                       \
    return (uflow_expand(uf, &cf, &sf) == uflow_type_connflow) ?        \
        &(cf->F) : &(sf->F);                                            \
}

