static err_t
aimcp_persist_cfg(struct aimcp_cfg *cfg,
                  struct profile_key *pkey,
                  struct hudproxy *proxy)
{
    err_t err = ERR_OK;

    /* mcp persistance encryption. */
    err = profile_get_string_alloc(pkey,
                                   "mcp_encryption_passphrase",
                                   0,
                                   &cfg->passphrase,
                                   &cfg->passphrase_len);
    if (err != ERR_OK) {
        AIMCP_TRACEF("mcp_encryption_passphrase fail");
        goto out;
    }
    if ((cfg->passphrase == NULL) || (cfg->passphrase_len == 0) ||
            (memcmp(cfg->passphrase, SCL("none")) == 0)) {
        err = ERR_VAL;
        goto out;
    }

    /* stat pointer. */
    cfg->pl = profile_listener_add(pkey,
                                   hudproxy_get_listener_name(proxy),
                                   hud_aimcp_stat_reset);

    NULL_CHECK(cfg->pl, err, ERR_MEM, out);
    cfg->stats = profile_listener_get_stats(cfg->pl);

