static err_t
hud_aimcp_init(struct hudfilter *this, struct hudproxy *proxy)
{
    struct aimcp_cfg *cfg = HUDFILTER_PRIVATE(this);
    struct profile_key *pkey;
    struct profile_key *persist_profile_key = NULL;
    struct profile_key *fallback_persist_profile_key = NULL;
    err_t err = ERR_OK;

    DBG_ASSERT("null check", NULL != cfg);

    memset(cfg, 0, sizeof(*cfg));
    *cfg = aimcp_default_cfg;

    /* Load attributes from aimcp profile. */
    pkey = profile_list_search(&proxy->profile_list,
                               "aimcp",
                               PROFILE_FLAG_ALL);

    if (pkey == NULL) {
        err = ERR_NOT_FOUND;
        goto out;
    }

    /* Find mcp persistence profile. */
    profile_list_persist_find_default_and_fallback(
            &proxy->profile_list,
            &persist_profile_key,
            &fallback_persist_profile_key);
    if (persist_profile_key == NULL) {
        AIMCP_TRACEF("Find TMM_PERSIST_MCP_SID with persist_profile_key == "
                     "NULL.\n");
    } else {
        AIMCP_TRACEF("Find TMM_PERSIST_MCP_SID with mode %u.\n",
                     persist_profile_key->persist_mode);
    }

    if ((persist_profile_key != NULL) &&
            (persist_profile_key->persist_mode == TMM_PERSIST_MCP_SID)) {
        AIMCP_TRACEF("Enter aimcp_persist_cfg with mode %u.\n",
                     persist_profile_key->persist_mode);
        err = aimcp_persist_cfg(cfg, persist_profile_key, proxy);
    }

out:
    if (err != ERR_OK) {
        hud_aimcp_uninit(this);
        AIMCP_TRACEF("End hud_aimcp_init with %E.\n", err);
    }
    return err;
}

