/*
 * Deconstruct an "augmented" Session Id, that is, one that has the original
 * MCP server's session id, but also backend pool member info, into its
 * constituent parts.
 * This overwrites null bytes into second argument, but it's OK since it's
 * all private calls with temporary buffers. Format is:
 *          pool_name;ip:port;original_mcp_sessionid
 */
static err_t
aimcp_parse_augmented_sessionid(struct aimcp_scb *scb,
                                BYTE *augmented,
                                SIZE aug_len)
{
    err_t err = ERR_OK;
    BYTE *sem;
    SIZE len;
    char *endptr;
    BYTE *ip_str, *port_str;
    SIZE ip_len, port_len;

    AIMCP_TRACEF("parsing >%.*s<", aug_len, augmented);
    sem = memchr(augmented, ';', aug_len);
    if (sem == NULL) {
        goto notfound;
    }
    len = sem - augmented;
    DBG_ASSERT("unset", NULL == scb->parsed.pool_name);
    scb->parsed.pool_name = mr_refstring_create(augmented, len);
    AIMCP_TRACEF("pool name %.*s", aug_len, augmented);

    aug_len -= (1 + len); /* +1 to skip the ; delimiter. */
    augmented = sem + 1;

    sem = memchr(augmented, ':', aug_len);
    if (sem == NULL) {
        goto notfound;
    }
    ip_str = augmented;
    ip_len = sem - augmented;

    augmented = sem + 1;
    aug_len -= (1 + ip_len); /* +1 to skip the : delimiter. */

    sem = memchr(augmented, ';', aug_len);
    if (sem == NULL) {
        goto notfound;
    }
    port_str = augmented;
    port_len = sem - augmented;

    augmented = sem + 1;
    aug_len -= (1 + port_len); /* +1 to skip the ; delimiter. */

    DBG_ASSERT("unset", NULL == scb->parsed.mcp_session_id);
    scb->parsed.mcp_session_id = mr_refstring_create(augmented, aug_len);
    AIMCP_TRACEF("session_id %s", augmented);

    /*
     * Port and IP require additional conversion.
     * Null terminate some bytes so we can call standard functions.
     */
    port_str[port_len] = '\0';
    scb->parsed.ip_tup.port = strtol(port_str, &endptr, AIMCP_STRTOL_BASE);
    DBG_ASSERT("conversion",
               (endptr != NULL) && (endptr != (char *)port_str) &&
                       ('\0' == *endptr));

    ip_str[ip_len] = '\0';
    scb->parsed.addr_size = tmm_inet_pton(ip_str,
                                          &scb->parsed.ip_tup.addr,
                                          &scb->parsed.ip_tup.rtdom_id);
    DBG_ASSERT("inet_pton",
               (scb->parsed.addr_size == sizeof(ip4_addr_t)) ||
                       (scb->parsed.addr_size == sizeof(ip6_addr_t)));
    AIMCP_TRACEF("IP tup %A:%u",
                 &scb->parsed.ip_tup.addr,
                 scb->parsed.ip_tup.port);
    if (-1 == scb->parsed.addr_size) {
        goto notfound;
    }

    goto out;

notfound:
    err = ERR_ARG;
out:
    AIMCP_TRACEF("returns %E", err);
    return err;
}

/* On success, populates scb->parsed */
static err_t
aimcp_decrypt_and_parse_sessionid(struct hudnode *node,
                                  union uflow *uf,
                                  void *data)
{
    struct aimcp_scb *scb = HUDNODE_CTX(node);
    struct http_data *hd = data;
    struct http_header_cache_info *ci = http_header_cache_info(hd);
    BYTE plain[AIMCP_SESSION_ID_BUF_SIZE], *outbuf = plain;
    SIZE outlen = sizeof(plain), value_len, min_size;
    xcursor_t xcur;
    err_t err;
    /* Irule can override the configured value in the profile */
    struct tmm_aes_key *tmp_key = (scb->tmm_aes_key_irule == NULL)
                                          ? scb->tmm_aes_key
                                          : scb->tmm_aes_key_irule;
    if (tmp_key == NULL) {
        AIMCP_TRACEF("Encryption keys %p irule key %p",
                     scb->tmm_aes_key,
                     scb->tmm_aes_key_irule);
        err = ERR_VAL;
        goto out;
    }

    /* Get length of the encrypted value. */
    err = http_header_value(ci, &xcur, &value_len, SCL(MCP_SESSION_ID));
    DBG_ASSERT("SID expected to be present", err == ERR_OK);
    ERR(err, out);
    AIMCP_TRACEF("header value %d %.*s", value_len, value_len, xcur);

    /* Is our stack buffer sufficient? */
    min_size = (tmp_key != NULL) ? http_decrypt_buffer_size(value_len)
                                 : value_len;
    if (min_size > outlen) {
        /* Nope, have to allocate. */
        outbuf = umalloc(min_size, M_FILTER, 0);
        NULL_CHECK(outbuf, err, ERR_MEM, out);
        outlen = min_size;
    } else {
        outlen = value_len;
    }

    /* Decrypt, or just base64 decode if key is NULL. */
    err = http_header_decrypt(ci,
                              SCL(MCP_SESSION_ID),
                              tmp_key,
                              outbuf,
                              &outlen);
    ERR(err, out);

    /* Parse out IP tuple and other parts. */
    err = aimcp_parse_augmented_sessionid(scb, outbuf, outlen);

out:
    if (outbuf != plain) {
        ufree(outbuf);
    }
    AIMCP_TRACEF("returns %E ", err);
    return err;
}

static BOOL
aimcp_method(struct hudnode *node, union uflow *uf, void *data)
{
    struct aimcp_scb *scb = HUDNODE_CTX(node);
    struct method_data *md = data;
    struct pool *pool;
    struct poolmbr *pmbr = NULL;
    BOOL ret = FALSE;

    DBG_ASSERT("Null check md", md != NULL);

    if (md->typeid != &hudfilter_aimcp_typeid) {
        goto out; /* Not for us. */
    }

    AIMCP_TRACEF("methodid %d ", md->methodid);
    switch (md->methodid) {
    case AIMCP_METHOD_PERSIST_PMBR:
        /* Look up pool member from ip:port parsed out of request header. */
        DBG_ASSERT("arg count", md->argc == AIMCP_PERSIST_PMBR_ARGC);
        pool = hudvariant_get_ptr(&md->argv[0]);
        AIMCP_TRACEF("pool %p ", pool);
        if (pool != NULL) {
            pmbr = poolmbr_find(pool, &scb->parsed.ip_tup);
        }
        AIMCP_TRACEF("pmbr %p ", pmbr);
        hudvariant_set_ptr(md->result, pmbr); /* Set result. May be NULL. */
        ret = TRUE;
        break;

    default:
        break;
    }
out:
    return ret;
}

static err_t
aimcp_request(struct hudnode *node, union uflow *uf, void *data)
{
    struct aimcp_scb *scb = HUDNODE_CTX(node);
    struct http_data *hd = data;
    struct http_header_cache_info *ci;
    struct xbuf *xb_hdr;
    err_t err = ERR_OK;
    xcursor_t xc;
    SIZE sid_len;

    ci = http_header_cache_info(hd);
    xb_hdr = http_header_xbuf(ci);
    /* Existence check. */
    err = http_header_value(ci, &xc, &sid_len, SCL(MCP_SESSION_ID));
    if (err == ERR_NOT_FOUND) {
        err = ERR_OK; /* No header, no worries. */
        goto out;
    }

    /*
     * Remember encrypted session id so we don't incur the cost to rebuild
     * for the response. Also, our encrypton generates different outputs
     * from the same inputs, and MCP spec wants a constant session id.
     */
    err = aimcp_header_construct(&scb->saved_sid, sid_len);
    ERR(err, out);
    scb->saved_sid.len =
            xbuf_extract(xb_hdr, xc, scb->saved_sid.buf, sid_len, NULL);
    /* This populates scb->parsed if successful. */
    err = aimcp_decrypt_and_parse_sessionid(node, uf, data);

    if (err != ERR_OK) {
        if (err != ERR_VAL) {
            goto out;
        }
        /* The passphrase could be not set so just do load balancing */
        err = ERR_OK;
        goto out;
    }

    err = http_header_replace(ci,
                              SCL(MCP_SESSION_ID),
                              scb->parsed.mcp_session_id->string,
                              scb->parsed.mcp_session_id->length);

out:
    return err;
}

static void
aimcp_handle_persist_picked(struct hudnode *node,
                            union uflow *uf,
                            struct persist_info *data)
{
    struct aimcp_scb *scb = HUDNODE_CTX(node);
    char *pname;
    struct profile_key pkey = {};
    err_t err = ERR_OK;
    BYTE tmpbuf[AIMCP_SESSION_ID_BUF_SIZE];
    SIZE tmplen;
    int ret;

    if ((data == NULL) || (data->mode != TMM_PERSIST_MCP_SID)) {
        AIMCP_TRACEF("Not ours %p mode %d",
                     data,
                     (data != NULL) ? data->mode : -1);
        goto out;
    }

    pname = data->handle;
    /* If explicit partition not specified, assume /Common. */
    if (*pname != '/') {
        ret = snprintf(tmpbuf, sizeof(tmpbuf), "/Common/%s", pname);
        if ((ret < 0) || (ret >= sizeof(tmpbuf))) {
            AIMCP_TRACEF("strncat->%d", ret);
            goto out;
        }
        pname = tmpbuf;
    }
    err = profile_find(pname, &pkey);
    if (err != ERR_OK) {
        AIMCP_TRACEF("profile_find %E", err);
        goto out;
    }

    err = profile_get_string(&pkey,
                             "mcp_encryption_passphrase",
                             0,
                             tmpbuf,
                             sizeof(tmpbuf),
                             &tmplen);
    if (err != ERR_OK) {
        AIMCP_TRACEF("profile_get_string %E", err);
        goto out;
    }
    scb->tmm_aes_key_irule =
            tmm_aes_key_from_pass(tmpbuf, tmplen, AIMCP_AES_KEY_LEN);
    if (scb->tmm_aes_key_irule == NULL) {
        AIMCP_TRACEF("tmm_aes_key_from_pass failed");
        goto out;
    }

out:
    return;
}

/*
 * Add persistence information to MCP_SESSION_ID header.
 * The format of the header is:
 *   pool_name;ip:port;original_value
 * where original_value is the value already present in the header.
 */
static err_t
hud_aimcp_add_persist(struct aimcp_scb *scb, struct http_data *hd)
{
    struct connflow *cs_cf = NULL, *cf = NULL;
    struct http_header_cache_info *ci = NULL;
    struct xbuf *xb_hdr = NULL;
    struct tmm_aes_key *tmp_key;
    BYTE plain[AIMCP_SESSION_ID_BUF_SIZE];
    BYTE *outbuf;
    err_t err = ERR_OK;
    char *pool_name = NULL;
    char *session_id = NULL;
    char addr_str[INET6_ADDRSTRLEN];
    char tuple_str[INET6_ADDRSTRLEN + sizeof("1234567")]; /* enough for [addr]:port */
    SIZE outlen = 0, persist_len = 0, sid_len = 0, sid_extracted_len = 0;
    ip_tuple_t tuple;
    xcursor_t cur;
    int ret;

    outbuf = plain;
    if ((scb == NULL) || (scb->uf == NULL) || (hd == NULL)) {
        err = ERR_VAL;
        goto out;
    }
    /* Irule can override the configured value in the profile */
    tmp_key = (scb->tmm_aes_key_irule == NULL) ? scb->tmm_aes_key
                                               : scb->tmm_aes_key_irule;
    if (tmp_key == NULL) {
        AIMCP_TRACEF("Encryption keys %p irule key %p",
                     scb->tmm_aes_key,
                     scb->tmm_aes_key_irule);
        err = ERR_VAL;
        goto out;
    }

    ci = http_header_cache_info(hd);
    DBG_ASSERT("http_header null check", NULL != ci);
    xb_hdr = http_header_xbuf(ci);

    cs_cf = uflow_get_connflow(scb->uf);
    cf = uflow_get_connflow(cs_cf->peer);
    if ((cf == NULL) || (cf->pmbr == NULL) || (cf->pmbr->pool == NULL)) {
        err = ERR_VAL;
        goto out;
    }

    pool_name = cf->pmbr->pool->name;
    tuple = cf->pmbr->tuple;

    /* ensure MCP_SESSION_ID header exists */
    err = http_header_value(ci, &cur, &sid_len, SCL(MCP_SESSION_ID));
    ERR(err, out);

    /*
     * If Mcp-Session-Id value and pool member IP + port haven't changed,
     * reuse saved augmented session id.
     */
    if ((scb->parsed.mcp_session_id != NULL) &&
            (xbuf_cmpbytes(xb_hdr, cur,
                    scb->parsed.mcp_session_id->string,
                    scb->parsed.mcp_session_id->length) == ERR_OK) &&
            IN6_ARE_ADDR_EQUAL(&scb->parsed.ip_tup.addr, &tuple.addr) &&
            (scb->parsed.ip_tup.port == tuple.port)) {
        AIMCP_TRACEF("Reusing request's Mcp-Session-Id: %.*s",
                     scb->saved_sid.len,
                     scb->saved_sid.buf);
        err = http_header_replace(ci,
                                  SCL(MCP_SESSION_ID),
                                  scb->saved_sid.buf,
                                  scb->saved_sid.len);
        goto out;
    }

    /* Build tuple string: IPv4 -> "a.b.c.d:port", IPv6 -> "[xxxx:...]:port"
     */
    if (IN6_IS_ADDR_V4(&tuple.addr)) {
        if (tmm_inet4_ntop(&tuple.addr, addr_str, INET_ADDRSTRLEN) == 0) {
            err = ERR_VAL;
            goto out;
        }
        ret = snprintf(tuple_str, sizeof(tuple_str), "%s:%u",
                addr_str, (unsigned)tuple.port);
        if ((ret < 0) || ((SIZE)ret >= sizeof(tuple_str))) {
            err = ERR_VAL;
            goto out;
        }
    } else {
        if (tmm_inet6_ntop(&tuple.addr, addr_str, INET6_ADDRSTRLEN) == 0) {
            err = ERR_VAL;
            goto out;
        }
        ret = snprintf(tuple_str, sizeof(tuple_str), "[%s]:%u",
                addr_str, (unsigned)tuple.port);
        if ((ret < 0) || ((SIZE)ret >= sizeof(tuple_str))) {
            err = ERR_VAL;
            goto out;
        }
    }

    AIMCP_TRACEF("tuple_str==%s\n", tuple_str);

    /*
     * Create persist string:
     * pool_name;ip:port; (include trailing ';')
     */
    persist_len = strlen(pool_name) + 1 /* ';' */ + strlen(tuple_str) +
                  1 /* ';' */;

    /* Is our stack buffer sufficient? */
    outlen = persist_len + sid_len;
    if ((outlen + 1) > sizeof(plain)) {
        /* Nope, have to allocate and end NULL char. */
        outbuf = umalloc(outlen + 1, M_FILTER, 0);
        NULL_CHECK(outbuf, err, ERR_MEM, out);
    }

    ret = snprintf(outbuf, persist_len + 1, "%s;%s;", pool_name, tuple_str);
    if ((ret < 0) || ((SIZE)ret >= persist_len + 1)) {
        err = ERR_VAL;
        goto out;
    }

    /* Add the existing MCP_SESSION_ID value after persist string. */
    session_id = outbuf + persist_len;
    sid_extracted_len =
            xbuf_extract(xb_hdr, cur, session_id, sid_len, NULL);
    if (sid_extracted_len != sid_len) {
        err = ERR_VAL;
        goto out;
    }
    session_id[sid_len] = '\0';

    DBG_ASSERT("buffer length check", strlen(outbuf) == outlen);
    AIMCP_TRACEF("outbuf==%s with strlen %d\n", outbuf, strlen(outbuf));

    DBG_ASSERT("NULL key", tmp_key != NULL);
    err = http_header_encrypt_and_set(ci,
                                      SCL(MCP_SESSION_ID),
                                      tmp_key,
                                      outbuf,
                                      outlen);

out:
    if (outbuf != plain) {
        ufree(outbuf);
    }
    AIMCP_TRACEF("returns %E ", err);
    return err;
}

static void
hud_aimcp_handler(struct hudnode *node,
                  hud_msg_t msg,
                  union uflow *uf,
                  void *data)
{
    struct aimcp_scb *scb = HUDNODE_CTX(node);
    const char *abort_reason = "";
    err_t err = ERR_OK;

    AIMCP_TRACEF("sees %s ", hud_msg_name_str(msg));
    switch (msg) {
    case HUDEVT_FLOW_INIT:
        if (uflow_isconnflow(uf)) {
            err = aimcp_pcb_init(node, uf);
            /* fall to scb init */
        }
        if (err == ERR_OK) {
            err = aimcp_scb_init(node, uf);
        }
        if (err != ERR_OK) {
            abort_reason = "FLOW_INIT error";
            goto abort;
        }

        /* Hold HUDEVT_ACCEPTED until we can inspect request headers. */
        hud_orbit_accepted_handling(node, uf, TRUE);
        break;

    case HUDEVT_REQUEST:
        err = aimcp_request(node, uf, data);
        if (err != ERR_OK) {
            abort_reason = "Mcp-Session-Id error";
            goto abort;
        }
        break;

    case HUDCTL_RESPONSE:
        err = hud_aimcp_add_persist(scb, data);
        if (err != ERR_OK) {
            AIMCP_TRACEF(
                    "Error augmenting session id with persistence info");
        }
        break;

    case HUDCTL_ABORT:
        /* FALLTHROUGH */
    case HUDCTL_TEARDOWN:
        if (uflow_isconnflow(uf)) {
            aimcp_pcb_reset(node, uf);
        }
        aimcp_scb_reset(node, uf);
        break;

    case HUDCTL_PERFORM_METHOD:
        if (aimcp_method(node, uf, data)) {
            /* Don't pass on if we handled it. */
            goto out;
        }
        break;

    case HUDEVT_PERSIST_PICKED:
        aimcp_handle_persist_picked(node, uf, data);
        break;

    default:
        break;
    }

    hud_orbit_handle_default(node, msg, uf, data);
    goto out;

abort:
    hud_orbit_handle_upper(node,
                           HUDEVT_ABORTED,
                           uf,
                           RST_WHY_ERR(uf, err, abort_reason));

out:
    return;
}

void
hud_aimcp_stat_reset(void *row)
{
    struct tmm_profile_aimcp_stat *stats =
            (struct tmm_profile_aimcp_stat *)row;

    if (stats == NULL) {
        goto done;
    }

done:
    return;
}

