#define JSON_APPLICATION_MERGE_PATCH_LEN \
                (sizeof(JSON_APPLICATION_MERGE_PATCH) - 1)
#define JSON_PREFIX ":JSON:"
#define JSON_MULTIPART                  "multipart/"
#define JSON_PATH_DELIM ':'
#define JSON_TOKENS_PER_ENTRY  3

/* SCB: Stream Control (flow) Block */
struct json_scb {
    union {
        struct http_data *http;  /* Ingress request data being held */
        struct sse_msg *sse;     /* Ingress sse msg data being held */
        struct hud_ref *msg_ref; /* Generic hud_ref for use with msg data */
    };
    char *http_cont_type;        /* Content-Type value with arg, umalloc()d. */
    struct mime_multipart *mime; /* Multipart lib instance handle (ingress). */
    struct tmm_json_cache *json; /* Ingress json cache parsing data */
    struct hud_orb_queue held_q; /* Q to hold msg evts/data while parsing */
    struct hud_orb_entry *queued_data_meta; /* Queued data meta in held_q */
    struct xbuf eg_rendered;     /* Xbuf to hold egress data to output */
    UINT32 payload_bytes;        /* JSON bytes buffered for req/msg */
    UINT32 non_json_bytes;       /* Non-JSON bytes buffered for req/msg */
    BOOL f_disabled : 1;
    BOOL f_held_accepted : 1;   /* HUDEVT_ACCEPTED is being held. */
    BOOL ingress_is_json : 1;   /* Current req/msg should contain JSON */
    BOOL egress_is_json : 1;    /* (could be in HTTP or Mime part header). */
    BOOL f_send_egress : 1;
    BOOL f_valid_parse : 1;     /* Complete JSON blob was parsed OK. */
    BOOL f_done : 1;            /* HUDEVT_REQ/RSP_DONE held for irule exec. */
    BOOL f_msg_done : 1;        /* HUDEVT_MSG_DONE held for irule exec. */
    BOOL ingress_is_multipart : 1;  /* HTTP body is Mime multipart. */
    BOOL egress_is_multipart : 1;
    BOOL f_json_part_rcvd : 1;   /* Complete JSON part has been extracted. */
    BOOL f_json_finished : 1;    /* Finished processing the JSON content. */
    BOOL f_ingress_msg_mode : 1; /* Ingress will arrive in HUDEVT_MESSAGEs */
    BOOL f_q_non_json_data : 1;  /* Queue ingress data (it's not JSON) */
};

/* Profile Config Info. */
struct json_cfg {

    /*
     * Limit to total size of JSON blob, to mitigate attack potential.
     * If body is Mime multipart, limit through end of JSON (first part).
     */
    UINT32 max_bytes;
    /*
     * Limit to size of JSMN token array, to mitigate attack potential.
     * Typical large JSON configs are mostly key:value pairs, plus some
     * overhead for structure. So we allow up to 3 tokens per "entry".
     */
    UINT32 max_entries;
    /*
     * Accept only Mime-conforming line endings (CRLF).
     * By default single LF line endings are tolerated.
     */
    BOOL mime_strict_crlf;
    /*
     * Limit for the size of any non-JSON payload in each message/request.
     * If non-JSON data comes before JSON, we have to queue it until we
     * finish the JSON parse and can forward it all.
     */
    UINT32 max_non_json_bytes;
};

/* Profile Config Defaults */
static const struct json_cfg cfg_template = {
        .max_bytes          = JSON_MAX_BYTES_DEFAULT,
        .max_entries        = JSON_MAX_ENTRIES_DEFAULT,
        .mime_strict_crlf   = FALSE,
        .max_non_json_bytes = JSON_MAX_OTHER_BYTES_DEFAULT,
};


/*
 * Manage JSON cache in http_data "opaque table".
 */

struct tmm_json_cache *
json_http_get_cache(struct http_data *hd)
{
    return tm_opaque_get(hd->tm_opaque_table, OPQ_HTTP_DATA_JSON_ID);
}

err_t
json_http_set_cache(struct http_data *hd, struct tmm_json_cache *json)
{
    err_t err = ERR_OK;
    void *opq;

    tm_opaque_delete(&hd->tm_opaque_table, OPQ_HTTP_DATA_JSON_ID);
    if (json == NULL) {
        goto out;
    }
    opq = tm_opaque_create(&hd->tm_opaque_table, OPQ_HTTP_DATA_JSON_ID, json);
    if (opq == NULL) {
        err = ERR_MEM;
    }

out:
    return err;
}

static void
json_http_delete_cache(struct http_data *hd)
{
    tm_opaque_delete(&hd->tm_opaque_table, OPQ_HTTP_DATA_JSON_ID);
}

static void
json_http_free_cache_cb(void *opaque)
{
    tmm_json_cache_release((struct tmm_json_cache*) opaque);
}

DECLARE_TM_OPQ(OPQ_HTTP_DATA_JSON_ID,
    .free = json_http_free_cache_cb);

struct tmm_json_cache *
json_msg_get_cache(struct hud_ref *ref)
{
    struct sse_msg *sse;
    struct tmm_json_cache *ret = NULL;

    switch (hud_ref_id_get(ref)) {
    case HUD_MSG_ID_HTTP:
    case HUD_MSG_ID_HTTP2_PUSH:
    case HUD_MSG_ID_HTTP_DATA:
        /* These are all "struct http_data". Look for json in opaques */
        ret = json_http_get_cache((struct http_data *) ref);
        break;
    case HUD_MSG_ID_SSE:
        sse = (struct sse_msg *) ref;
        ret = sse->ctx;
        break;
    default:
        /* Some other request type, not supporting JSON cache. */
        break;
    }

    return ret;
}

/*
 * Manage mime_multipart instance in http_data "opaque table".
 */

struct mime_multipart *
json_http_get_multipart(struct http_data *hd)
{
    return tm_opaque_get(hd->tm_opaque_table, OPQ_HTTP_DATA_MIME_ID);
}

err_t
json_http_set_multipart(struct http_data *hd, struct mime_multipart *mmp)
{
    err_t err = ERR_OK;
    void *opq;

    tm_opaque_delete(&hd->tm_opaque_table, OPQ_HTTP_DATA_MIME_ID);
    if (mmp == NULL) {
        goto out;
    }
    opq = tm_opaque_create(&hd->tm_opaque_table, OPQ_HTTP_DATA_MIME_ID, mmp);
    if (opq == NULL) {
        err = ERR_MEM;
    }

out:
    return err;
}

static void
json_http_delete_multipart(struct http_data *hd)
{
    tm_opaque_delete(&hd->tm_opaque_table, OPQ_HTTP_DATA_MIME_ID);
}

static void
json_http_free_multipart_cb(void *opaque)
{
    mime_multipart_release((struct mime_multipart*) opaque);
}

DECLARE_TM_OPQ(OPQ_HTTP_DATA_MIME_ID,
    .free = json_http_free_multipart_cb);


/*
 * Support for JSON path lookup. Used by "MESSAGE::field" iRule commands.
 * See descriptions in json_filter.h .
 */

BOOL
json_http_key_is_json(const char *key_path)
{
    return strncmp(key_path, JSON_PREFIX, sizeof(JSON_PREFIX) - 1) == 0;
}

struct tmm_json_value *
json_http_path_lookup(struct http_data *hd, const char *key_path, SIZE kplen,
                      unsigned index, unsigned *nrepp)
{
    char key[kplen + 1];
    char *keyp;
    char *nextp;
    char c;
    struct tmm_json_cache *jcache;
    struct tmm_json_value *jval = NULL;
    struct tmm_json_value *jvtmp = NULL;
    struct tmm_json_array *jarr;
    struct tmm_json_object *jobj;
    bool indexing_root_element;
    void *jcur = NULL;
    unsigned idx = 0;
    unsigned long arrIdx;
    char *idxParseEnd;
    err_t err;

    if (!json_http_key_is_json(key_path)) {
        goto out;
    }

    jcache = json_http_get_cache(hd);
    if (jcache == NULL) {
        goto out;
    }

    err = tmm_json_cache_get_root(jcache, &jval);
    if (err != ERR_OK) {
        goto out;
    }

    /* Copy the key path so we can parse it in place. */
    strlcpy(key, key_path, kplen + 1);

    /*
     * Are we indexing the root element? We already checked that path starts
     * with :JSON:, so just check length here. If so, allow one trip into
     * below loop where if it's an object/array, there's no key so it will
     * fail to index. If it's a leaf type it gets returned as desired.
    */
    indexing_root_element = (sizeof(JSON_PREFIX) - 1) == kplen;

    /*
     * Iterate through the path until we get to the leaf or null terminator.
     * Allow the indexing root case to enter the loop to be handled.
     */
    for (keyp = &key[sizeof(JSON_PREFIX) - 1];
            ((*keyp != '\0') || indexing_root_element);
            keyp = nextp) {

        /* Find the end of the current key/index string */
        for (nextp = keyp; c = *nextp, (c != '\0'); nextp++) {
            /* Check if special char is escaped with a duplicate or not */
            if (c == JSON_PATH_DELIM) {
                if (*(nextp+1) == c) {
                    /* Escaped char. Eliminate dup and keep parsing str */
                    nextp++;
                    memmove(nextp, nextp+1, (key + kplen - nextp));
                } else {
                    break;
                }
            }
        }

        if (c == JSON_PATH_DELIM) {
            *nextp++ = '\0';
        }

        /* Expect a JSON object or array. */
        switch (tmm_json_value_type(jval)) {
        case JSON_TYPE_OBJECT:
            err = tmm_json_value_get_object(jval, &jobj);
            if (err != ERR_OK) {
                break;
            }
            if ((*nextp == '\0') && ((index != 0) || (nrepp != NULL))) {
                /* At leaf and looking for replicates, scan for index. */
                idx = 0;
                do {
                    err = tmm_json_object_get_next(jobj, keyp, &jcur, &jval);
                } while ((err == ERR_OK) && (idx++ < index));
                if ((err == ERR_OK) && (nrepp != NULL)) {
                    /* If needed, count the rest of the replicates. */
                    do {
                        err = tmm_json_object_get_next(jobj, keyp, &jcur,
                                &jvtmp);
                    } while ((err == ERR_OK) && (idx++, TRUE));
                    if (err == ERR_NOT_FOUND) {
                        err = ERR_OK;
                    }
                }
            } else {
                err = tmm_json_object_get(jobj, keyp, &jval);
            }
            if (err != ERR_OK) {
                break;
            }
            break;
        case JSON_TYPE_ARRAY:
            err = tmm_json_value_get_array(jval, &jarr);
            if (err != ERR_OK) {
                break;
            }
            arrIdx = strtoul(keyp, &idxParseEnd, 0);
            if (idxParseEnd == keyp) {
                /* Invalid numeric string */
                err = ERR_VAL;
                break;
            }

            err = tmm_json_array_get(jarr, (UINT32) arrIdx, &jval);
            if (err != ERR_OK) {
                break;
            }
        default:
            /* Only time we hit this is if root is not a collection */
            idx = 1;
            break;
        }

        if (err != ERR_OK) {
            break;
        }

        switch(tmm_json_value_type(jval)) {
        case JSON_TYPE_STRING:
        case JSON_TYPE_LITERAL:
        case JSON_TYPE_INTEGER:
        case JSON_TYPE_BOOL:
            /* Found leaf. Should be at end of path. */
            if (*nextp == '\0') {
                /* Success! */
                if (nrepp != NULL) {
                    *nrepp = idx;
                }
                goto out;
            }
            break;
        case JSON_TYPE_OBJECT:
        case JSON_TYPE_ARRAY:
            /* Iterate to next key in path. */
            continue;
        default:
            break;
        }

        break;
    }
    /* Failed. */
    jval = NULL;

out:
    return jval;
}

/*
 * Flush (empty) the held msg event/data queue.
 * If send_up, send the events/data up the hudchain.
 * Otherwise, just empty the queue and sink it all.
 */
static void
json_flush_held_queue(struct json_scb *scb, struct hudnode *node,
        union uflow *uf, BOOL send_up)
{
    struct hud_orb_entry *entry;
    hud_msg_t msg;
    void *data;

    scb->queued_data_meta = NULL;
    while (!hud_orbit_queue_empty(&scb->held_q)) {
        entry = hud_orbit_pop_queue(&scb->held_q);
        if (send_up) {
            if (hud_orbit_entry_is_xb_raw(entry)) {
                hud_orbit_process_upper(node, uf, hud_orbit_entry_xb(entry));
            } else {
                hud_orbit_entry_msg(entry, &msg, &data);
                hud_orbit_handle_upper(node, msg, uf, data);
            }
        } else {
            hud_orbit_free_entry_contents(entry);
        }
        hud_orbit_free_entry(entry);
    }
}

/*
 * Filter config init/uninit.
 */

static void
hud_json_uninit(struct hudfilter *this)
{
}

static err_t
hud_json_init(struct hudfilter *this, struct hudproxy *proxy)
{
    err_t err = ERR_OK;

    struct json_cfg *cfg;
    struct profile_key *pkey;

    pkey = profile_list_search(&proxy->profile_list, "json",
                    PROFILE_FLAG_ALL);
    if (pkey == NULL) {
        err = ERR_NOT_FOUND;
        goto out;
    }

    cfg = HUDFILTER_PRIVATE(this);
    memcpy(cfg, &cfg_template, sizeof(struct json_cfg));

    profile_get_uint32(pkey, "maximum_bytes", 0, &cfg->max_bytes);
    profile_get_uint32(pkey, "maximum_entries", 0, &cfg->max_entries);
    profile_get_bool(pkey, "mime_strict_crlf", 0, &cfg->mime_strict_crlf);
    profile_get_uint32(pkey, "maximum_non_json_bytes", 0,
            &cfg->max_non_json_bytes);

out:
    if (err != ERR_OK) {
        hud_json_uninit(this);
    }
    return err;
}

/*
 * Stream SCB init/uninit.
 */

static void
hud_json_init_scb(struct json_scb *scb, union uflow *uf)
{
    memset(scb, 0, sizeof(*scb));

    hud_orbit_queue_init(&scb->held_q);
    xbuf_embed_init(&scb->eg_rendered, uflow_mss(uf));
    scb->f_send_egress = TRUE;
}

static void
hud_json_uninit_scb(struct json_scb *scb)
{
    tmm_json_cache_release(scb->json);
    scb->json = NULL;
    mime_multipart_release(scb->mime);
    scb->mime = NULL;
    ufree(scb->http_cont_type);
    scb->http_cont_type = NULL;
    xbuf_free(&scb->eg_rendered);
    hud_ref_release(scb->msg_ref);
    json_flush_held_queue(scb, NULL, NULL, FALSE);
}

/*
 * Forward HUDEVT_ACCEPTED if it was held earlier and not yet forwarded.
 */
static void
json_filter_forward_accepted(struct hudnode *node, struct json_scb *scb,
        union uflow *uf)
{
    if (scb->f_held_accepted) {
        hud_orbit_handle_upper(node, HUDEVT_ACCEPTED, uf, NULL);
        scb->f_held_accepted = FALSE;
    }
}

/*
 * After processing the ingress req/resp/msg and forwarding it, reset state
 * as necessary to prepare to process another req/resp/msg through the filter.
 */
static void
json_filter_reset_ingress_for_reuse(struct json_scb *scb)
{
    hud_ref_release(scb->msg_ref);
    scb->msg_ref = NULL;
    tmm_json_cache_release(scb->json);
    scb->json = NULL;
    mime_multipart_release(scb->mime);
    scb->mime = NULL;
    ufree(scb->http_cont_type);
    scb->http_cont_type = NULL;
    scb->payload_bytes = 0;
    scb->non_json_bytes = 0;
    scb->f_json_part_rcvd = FALSE;
    scb->f_valid_parse = FALSE;
    scb->f_json_finished = FALSE;
    scb->ingress_is_json = FALSE;
    scb->ingress_is_multipart = FALSE;
    scb->f_q_non_json_data = FALSE;
    json_flush_held_queue(scb, NULL, NULL, FALSE);
}

/*
 * Continue after completion of iRule event.
 */
static void
json_filter_handle_tcl_event_success(struct hudnode *node, union uflow *uf,
        tclrule_t rule_event, struct json_scb *scb)
{
    if (scb->f_ingress_msg_mode) {
        hud_orbit_handle_upper(node, HUDEVT_MESSAGE, uf, scb->msg_ref);
        json_flush_held_queue(HUDNODE_CTX(node), node, uf, TRUE);
        if (scb->f_msg_done) {
            scb->f_msg_done = FALSE;
            json_filter_reset_ingress_for_reuse(scb);
        } else {
            hud_ref_release(scb->msg_ref);
            scb->msg_ref = NULL;
        }
        goto out;
    }

    switch (rule_event) {
    case TCLRULE_JSON_REQUEST:
    case TCLRULE_JSON_REQUEST_MISSING:
    case TCLRULE_JSON_REQUEST_ERROR:
        /* Forward held messages. */
        json_filter_forward_accepted(node, scb, uf);
        hud_orbit_handle_upper(node, HUDEVT_REQUEST, uf, scb->http);
        json_flush_held_queue(HUDNODE_CTX(node), node, uf, TRUE);
        if (scb->f_done) {
            scb->f_done = FALSE;
            scb->f_ingress_msg_mode = FALSE;
            json_filter_reset_ingress_for_reuse(scb);
        } else {
            http_data_release(scb->http);
            scb->http = NULL;
        }
        break;

    case TCLRULE_JSON_RESPONSE:
    case TCLRULE_JSON_RESPONSE_MISSING:
    case TCLRULE_JSON_RESPONSE_ERROR:
        /* Forward held messages. */
        hud_orbit_handle_upper(node, HUDEVT_RESPONSE, uf, scb->http);
        json_flush_held_queue(HUDNODE_CTX(node), node, uf, TRUE);
        if (scb->f_done) {
            scb->f_done = FALSE;
            scb->f_ingress_msg_mode = FALSE;
            json_filter_reset_ingress_for_reuse(scb);
        } else {
            http_data_release(scb->http);
            scb->http = NULL;
        }
        break;

    default:
        /* Shouldn't hit this. */
        DBG_ASSERT("Bad default case json tcl event", FALSE);
        break;
    }

out:
    return;
}

/*
 * Raise iRule Event.
 */
static void
json_filter_raise_tcl_event(struct hudnode *node, union uflow *uf,
        tclrule_t rule_event, struct json_scb *scb)
{
    err_t err = ERR_OK;

    JSON_TRACEF(uf, "raising Tcl event %s",
            dynamic_tcl_get_event_name(rule_event, NULL));
    err = tclrule_execute_msg(node, uf, rule_event, scb->msg_ref);
    if (err == ERR_INPROGRESS) {
        hud_orbit_pause_ingress(node);
        goto out;
    }
    if (err != ERR_OK) {
        JSON_IRULE_ERROR_LOG(CFSTR(uf), err,
                dynamic_tcl_get_event_name(rule_event, NULL));
        hud_orbit_handle_upper(node, HUDEVT_ABORTED, uf,
                RST_WHY_ERR(uf, ERR_VAL, "JSON filter iRule error"));
        goto out;
    }
    json_filter_handle_tcl_event_success(node, uf, rule_event, scb);
out:
    return;
}

/*
 * Extract a NUL-terminated string from an xbuf and store in a umalloc'd buffer.
 * Return the string value. Caller must ufree() it later.
 */
static char *
json_filter_extract_string_from_xbuf(struct xbuf *xb, xcursor_t xc, SIZE len)
{
    xcursor_t xc_tmp;
    char *str = NULL;
    size_t n;

    str = umalloc(len + 1, M_JSON, 0);
    if (str == NULL) {                  /* Shouldn't happen. */
        goto out;
    }

    n = xbuf_extract(xb, xc, str, len, &xc_tmp);
    if (n != len) {
        ufree(str);
        str = NULL;
        goto out;
    }
    str[n] = '\0';

out:
    return str;
}

/*
 * Check HTTP Content-Type header for presence and whether it is JSON or
 * Mime Multipart. Set SCB flags (ingress_is_json or ingress_is_multipart)
 * accordingly, and return ERR_OK if present and one of those,
 * else ERR_NOT_FOUND.
 */
static err_t
json_filter_check_http_content_type(struct hudnode *node,
        union uflow *uf, struct http_data *http)
{
    struct json_scb *scb = HUDNODE_CTX(node);
    xcursor_t val_cur;
    SIZE val_len = 0;
    err_t err = ERR_OK;

    /* Check presence of "Content-Type" header. */
    err = http_cached_header_value(&http->ci, &val_cur, &val_len,
            HTTP_HID_CONTENT_TYPE);
    if (err != ERR_OK) {
        err = ERR_NOT_FOUND;
        goto out;
    }

    if (node->f_serverside &&
            JSON_CONTENT_TYPE_MATCH(&http->ci.xb_hdrs, val_cur, JSON_TEXT_EVENT_STREAM)) {
        /* Multiple JSON payloads will arrive in HUDEVT_MESSAGEs */
        scb->f_ingress_msg_mode = TRUE;
        goto out;
    }

        /* Check for multipart content-type using direct xbuf comparison */
    if (JSON_CONTENT_TYPE_MATCH(&http->ci.xb_hdrs, val_cur, JSON_MULTIPART)) {
        /* JSON content could be in a Mime multipart. */
        /* Only allocate string for multipart case since mime lib needs it */
        DBG_ASSERT("JSON clear http_cont_type", scb->http_cont_type == NULL);
        scb->http_cont_type = json_filter_extract_string_from_xbuf(
                &http->ci.xb_hdrs, val_cur, val_len);
        if (scb->http_cont_type == NULL) {
            err = ERR_NOT_FOUND;
            goto out;
        }

        scb->ingress_is_multipart = TRUE;
        goto out;
    }

    if (JSON_CONTENT_TYPE_MATCH(&http->ci.xb_hdrs, val_cur, JSON_APPLICATION) ||
        JSON_CONTENT_TYPE_MATCH(&http->ci.xb_hdrs, val_cur, JSON_APPLICATION_PROBLEM) ||
        JSON_CONTENT_TYPE_MATCH(&http->ci.xb_hdrs, val_cur, JSON_APPLICATION_3GPPHAL) ||
        JSON_CONTENT_TYPE_MATCH(&http->ci.xb_hdrs, val_cur, JSON_APPLICATION_JSON_PATCH) ||
        JSON_CONTENT_TYPE_MATCH(&http->ci.xb_hdrs, val_cur, JSON_APPLICATION_MERGE_PATCH)) {
        /* JSON content is directly in the HTTP message body. */
        scb->ingress_is_json = TRUE;
        goto out;
    }

    /* JSON content is definitely missing. */
    err = ERR_NOT_FOUND;
out:
    return err;
}

/*
 * Prepare to parse JSON content. Init the JSON cache.
 */
static err_t
json_filter_prepare_to_parse(struct json_scb *scb, union uflow *uf,
        struct json_cfg *cfg)
{
    err_t err = ERR_OK;

    DBG_ASSERT("JSON cache cleared from last parse", scb->json == NULL);
    err = tmm_json_cache_create(&scb->json, 3 * cfg->max_entries,
            uflow_mss(uf));
    if (err != ERR_OK) {
        scb->json = NULL;
        goto out;
    }

out:
    return err;
}

/*
 * Recover raw multipart ingress for forwarding, and raise MISSING iRule event.
 * TODO: Should we use this also for non-multipart?
 */
static void
json_filter_handle_json_missing(struct hudnode *node, struct json_scb *scb,
        union uflow *uf)
{
        struct xbuf xb;

        DBG_ASSERT("Content-Type is multipart", scb->ingress_is_multipart);
        if (scb->mime != NULL) {
            /* Only push back ingress if we've consumed any. */
            xbuf_embed_init(&xb, uflow_mss(uf));
            mime_multipart_render(scb->mime, &xb);
            if (xb.len != 0) {
                hud_orbit_pushback_ingress(node, uf, &xb); /* Sets PAUSE flag */
                hud_orbit_unpause_ingress(node, uf);       /*    so unset it. */
            }
        }
        scb->f_json_finished = TRUE;
        json_filter_raise_tcl_event(node, uf, (uflow_is_clientside(uf) ? 
                TCLRULE_JSON_REQUEST_MISSING : TCLRULE_JSON_RESPONSE_MISSING),
                scb);
}

/*
 * Recover raw ingress for forwarding, and raise ERROR iRule event.
 * Optional xb_new contains current ingress not yet consumed by the multipart.
 * XXX: Fix this scenario for multipart mode - currently, the JSON part is
 *      forwarded with an empty body, instead of recovering it.
 */
static err_t
json_filter_handle_json_error(struct hudnode *node, struct json_scb *scb,
        union uflow *uf, struct xbuf *xb_new)
{
    struct hud_orb_entry *orb_entry;
    struct xbuf xb;
    err_t err = ERR_OK;

    if (scb->ingress_is_multipart) {
        xbuf_embed_init(&xb, uflow_mss(uf));
        if (scb->mime != NULL) {
            mime_multipart_render(scb->mime, &xb);
        }
        if (xb.len != 0) {
            hud_orbit_pushback_ingress(node, uf, &xb); /* Sets PAUSE flag */
            hud_orbit_unpause_ingress(node, uf);       /*    so unset it. */
        }
        if ((xb_new != NULL) && (xb_new->len != 0)) {
            hud_orbit_pushback_ingress(node, uf, xb_new);
            hud_orbit_unpause_ingress(node, uf);
        }
    } else {
        if (scb->f_ingress_msg_mode) {
            if (scb->queued_data_meta != NULL) {
                xbuf_embed_init(&xb, uflow_mss(uf));
                /* 
                 * Recover any in-progress payload from the parser to
                 * forward as the body of our 'data' SSE meta.
                 */
                tmm_json_cache_recover_raw(scb->json, &xb);
                orb_entry = hud_orbit_create_entry_xb(&xb, 0);
                if (orb_entry == NULL) {
                    err = ERR_MEM;
                    goto out;
                }
                hud_orbit_queue_insert_after_entry(&scb->held_q,
                        scb->queued_data_meta, orb_entry);
            }
        } else {
            /* 
             * This is the standard json-in-http case.
             * Recover any in-progress payload from the parser to
             * forward through to the server.
             */
            xbuf_embed_init(&xb, uflow_mss(uf));
            tmm_json_cache_recover_raw(scb->json, &xb);
            orb_entry = hud_orbit_create_entry_xb(&xb, 0);
            if (orb_entry == NULL) {
                err = ERR_MEM;
                goto out;
            }
            hud_orbit_queue_insert_tail_entry(&scb->held_q, orb_entry);
        }

        /* If there was yet-to-be-buffered ingress, q until irule is done */
        if ((xb_new != NULL) && (xb_new->len != 0)) {
            orb_entry = hud_orbit_create_entry_xb(xb_new, 0);
            if (orb_entry == NULL) {
                err = ERR_MEM;
                goto out;
            }
            hud_orbit_queue_insert_tail_entry(&scb->held_q, orb_entry);
        }
    }

    scb->f_json_finished = TRUE;
    json_filter_raise_tcl_event(node, uf, (uflow_is_clientside(uf) ? 
            TCLRULE_JSON_REQUEST_ERROR : TCLRULE_JSON_RESPONSE_ERROR), scb);

out:
    return err;
}

/*
 * Handle checks and raise iRules events after JSON payload has been completely
 * received. Attach the JSON cache and any mime multipart, and send the message.
 * Return ERR_OK only if a tcl event was successfully raised.
 */
static err_t
json_filter_handle_json_complete(struct hudnode *node, struct json_scb *scb,
        union uflow *uf)
{
    err_t err = ERR_OK;

    DBG_ASSERT("Can only be here if content is JSON", scb->ingress_is_json);
    if (scb->payload_bytes == 0 ||
            (scb->f_valid_parse && tmm_json_cache_is_empty(scb->json))) {
        /*
         * This case covers if no JSON payload ever arrived, or if it was
         * all whitespace so no json values were found in the payload
         */
        JSON_NO_CONTENT_LOG(CFSTR(uf));
        json_filter_raise_tcl_event(node, uf, (uflow_is_clientside(uf) ? 
                TCLRULE_JSON_REQUEST_MISSING : TCLRULE_JSON_RESPONSE_MISSING),
                scb);
        goto out;
    }
    if (!scb->f_valid_parse) {
        /* Incomplete JSON content. Parse errors are handled in ingress. */
        JSON_CONTENT_ERROR_LOG(CFSTR(uf), err);
        err = json_filter_handle_json_error(node, scb, uf, NULL);
        goto out;
    }

    /* Parsed valid JSON body. Attach the tmm_json_cache. */
    if (scb->f_ingress_msg_mode) {
        scb->sse->ctx = tmm_json_cache_addref(scb->json);
        scb->sse->ctx_free = (void (*)(void*))tmm_json_cache_release;
    } else {

        err = json_http_set_cache(scb->http,
                tmm_json_cache_addref(scb->json));
        if (err != ERR_OK) {
            goto out;
        }

        /* If multipart, attach the mime multipart instance. */
        if (scb->ingress_is_multipart) {
            err = json_http_set_multipart(scb->http,
                    mime_multipart_addref(scb->mime));
            if (err != ERR_OK) {
                goto out;
            }
        }
    }

    /*
     * Raise event for successful JSON parse. Tcl function/callback will
     * forward necessary messages on tcl success, so don't forward here.
     */
    json_filter_raise_tcl_event(node, uf, (uflow_is_clientside(uf) ? 
            TCLRULE_JSON_REQUEST : TCLRULE_JSON_RESPONSE), scb);

out:
    return err;
}

/*
 * HUDCTL_PERFORM_METHOD handler
 *  Returns TRUE if we should continue forwarding down.
 */
static BOOL
json_filter_handle_perform_method(struct hudnode *node,
        union uflow *uf, struct method_data *md)
{
    BOOL keep_forwarding_down = TRUE;

    switch (md->methodid)
    {
    case HTTP_METHOD_RESPOND:
        if ((md->typeid == &hudfilter_http_typeid) &&
                http_generic_method_respond(node, uf, md, NULL)) {
            keep_forwarding_down = FALSE;
        }
        break;

    default:
        break;
    }

    return keep_forwarding_down;
}

/*
 * HUD message handler.
 */
static void
hud_json_handler(struct hudnode *node, hud_msg_t msg,
        union uflow *uf, void *data)
{
    struct json_scb *scb = HUDNODE_CTX(node);
    struct json_cfg *cfg = HUDNODE_PRIVATE(node);
    struct tmm_json_cache *eg_json;
    struct mime_multipart *eg_mime = NULL;
    struct http_data *eg_hd = NULL;
    struct enable_data *enable_data;
    struct sse_meta *sse_meta;
    struct hud_orb_entry *orb_entry;
    bool data_meta, is_sse;
    UINT64 content_len;
    tclrule_t rule_event;
    err_t err = ERR_OK;

    JSON_TRACEF(uf, "sees %s ", hud_msg_name_str(msg));

    if (scb == NULL) {
        goto forward;
    }

    if (scb->f_disabled && (msg != HUDCTL_ENABLE) && (msg != HUDEVT_TCL)) {
        /* Flow disabled; forward immediately. */
        goto forward;
    }

    switch (msg) {
    case HUDEVT_FLOW_INIT:
        hud_json_init_scb(scb, uf);
        goto forward;

    case HUDCTL_ENABLE:
        enable_data = data;
        if (enable_data->typeid == HUDNODE_TYPEID(node)) {
            scb->f_disabled = !enable_data->enable;
            enable_data->err = ERR_OK;
            goto out;
        }
        goto forward;

    case HUDEVT_EOF:
    case HUDEVT_SHUTDOWN:
    case HUDCTL_SHUTDOWN:
        goto forward;

    case HUDCTL_ABORT:
    case HUDCTL_TEARDOWN:
        hud_json_uninit_scb(scb);
        goto forward;

    case HUDEVT_ACCEPTED:
        /* Hold HUDEVT_ACCEPTED until we send HUDEVT_REQUEST up. */
        scb->f_held_accepted = TRUE;
        goto out;

    case HUDEVT_META:
        if ((!scb->ingress_is_multipart && !scb->ingress_is_json) ||
                scb->f_json_finished) {
            goto forward;
        }
        data_meta = FALSE;
        if (hud_ref_id_get(data) == HUD_MSG_ID_SSE_META) {
            sse_meta = data;
            if (sse_meta->field_name == SSE_FIELD_DATA) {
                data_meta = TRUE;
                scb->f_q_non_json_data = FALSE;
                if (scb->queued_data_meta != NULL) {
                    /* Only keep one data 'meta' block for rendered json */
                    hud_ref_release(data);
                    goto out;
                }
            } else {
                scb->f_q_non_json_data = TRUE;
            }
        }
        /* Queue the HUDEVT_META to be released with the rest of the msg */
        orb_entry = hud_orbit_create_entry_msg(msg, data, 0, 0);
        if (orb_entry == NULL) {
            err = ERR_MEM;
            goto abort;
        }
        if (data_meta) {
            scb->queued_data_meta = orb_entry;
        }
        hud_orbit_queue_insert_tail_entry(&scb->held_q, orb_entry);
        goto out;

    case HUDCTL_META:
        if (!scb->f_send_egress) {
            /* Dropping the message */
            hud_ref_release(data);
            goto out;
        }
        if (hud_ref_id_get(data) == HUD_MSG_ID_SSE_META) {
            sse_meta = data;
            if ((sse_meta->field_name == SSE_FIELD_DATA) &&
                    (scb->eg_rendered.len > 0)) {
                /* The time has come, to egress rendered JSON */
                scb->egress_is_json = TRUE;
                hud_orbit_handle_lower(node, msg, uf, data);
                hud_orbit_process_lower(node, uf, &scb->eg_rendered);
                goto out;
            }
            scb->egress_is_json = FALSE;
        }
        goto forward;

    case HUDEVT_REQUEST:
    case HUDEVT_RESPONSE:
        DBG_ASSERT("have struct http_data *", data != NULL);

        err = json_filter_check_http_content_type(node, uf, data);
        if ((err == ERR_OK) && scb->f_ingress_msg_mode) {
            json_filter_forward_accepted(node, scb, uf);
            goto forward;
        }
        scb->http = data;
        http_data_addref(scb->http);
        if (err == ERR_NOT_FOUND) {
            JSON_NO_CONTENT_TYPE_LOG(CFSTR(uf));
            json_filter_raise_tcl_event(node, uf, (uflow_is_clientside(uf) ?
                    TCLRULE_JSON_REQUEST_MISSING :
                    TCLRULE_JSON_RESPONSE_MISSING), scb);
            /* Forward msgs after irule execution finishes */
            goto out;
        }
        if (err != ERR_OK) {
            goto abort;
        }

        if (http_get_chunk_encoding(data)) {
            /* Ensure parser is only fed unchunked ingress. */
            http_payload_unchunk(data, node, uf);
        }

        if (scb->ingress_is_multipart) {
            goto out;
        }

        /* Have JSON in the main message body. Prepare to parse JSON. */
        err = json_filter_prepare_to_parse(scb, uf, cfg);
        if (err != ERR_OK) {
            goto abort;
        }
        /* Messages will be forwarded after irule execution completes. */
        goto out;

    case HUDEVT_MESSAGE:
        DBG_ASSERT("Unexpected HUDEVT_MESSAGE in JSON",
                scb->f_ingress_msg_mode);

        DBG_ASSERT("JSON only supports SSE messages currently",
                hud_ref_id_get(data) == HUD_MSG_ID_SSE);
        scb->sse = sse_msg_addref(data);

        /* In message mode, assume every message should be JSON for now */
        scb->ingress_is_json = TRUE;
        err = json_filter_prepare_to_parse(scb, uf, cfg);
        if (err != ERR_OK) {
            goto abort;
        }
        /* HUDEVT_MESSAGE will be forwarded after irule execution. */
        goto out;

    case HUDEVT_MESSAGE_DONE:
        DBG_ASSERT("Unexpected HUDEVT_MESSAGE_DONE in JSON",
            scb->f_ingress_msg_mode);
    case HUDEVT_REQUEST_DONE:
    case HUDEVT_RESPONSE_DONE:
        if ((!scb->ingress_is_multipart && !scb->ingress_is_json) ||
                scb->f_json_finished) {
            if (scb->f_ingress_msg_mode) {
                if (msg == HUDEVT_MESSAGE_DONE) {
                    json_filter_reset_ingress_for_reuse(scb);
                } else {
                    scb->f_ingress_msg_mode = FALSE;
                }
            } else {
                json_filter_reset_ingress_for_reuse(scb);
            }
            goto forward;
        }

        /* JSON is expected in a multipart, but it's not there. */
        if (scb->ingress_is_multipart && !scb->ingress_is_json) {
            JSON_NO_CONTENT_TYPE_LOG(CFSTR(uf));
            json_filter_handle_json_missing(node, scb, uf);
        } else {
            /*
             * Have JSON in the main message body. If we don't have a
             * valid parse yet, try getting one by telling the parser
             * that no more data is coming. Regardless of outcome, check
             * results, attach JSON cache to http_data, and/or raise event.
             */
            if (!scb->f_valid_parse) {
                err = tmm_json_cache_parse_complete(scb->json);
                if (err == ERR_OK) {
                    scb->f_valid_parse = TRUE;
                }
            }
            err = json_filter_handle_json_complete(node, scb, uf);
            if (err != ERR_OK) {
                goto abort; /* Internal error. */
            }
        }

        /*
         * If we are not holding a msg ref, we can send up the *_DONE event
         * immediately - otherwise, an irule is still running so we queue
         * it (it will be released up the chain after the irule finishes).
         */
        if (scb->msg_ref == NULL) {
            json_filter_reset_ingress_for_reuse(scb);
            if (msg != HUDEVT_MESSAGE_DONE) {
                scb->f_ingress_msg_mode = FALSE;
            }
            goto forward;
        }

        orb_entry = hud_orbit_create_entry_msg(msg, data, 0, 0);
        if (orb_entry == NULL) {
            err = ERR_MEM;
            goto abort;
        }
        hud_orbit_queue_insert_tail_entry(&scb->held_q, orb_entry);

        /* Defer state finilization for after irule processing */
        if (msg == HUDEVT_MESSAGE_DONE) {
            scb->f_msg_done = TRUE;
        } else {
            scb->f_done = TRUE;
        }
        goto out;

    case HUDCTL_REQUEST:
    case HUDCTL_RESPONSE:
        DBG_ASSERT("have struct http_data *", data != NULL);
        eg_hd = data;
        if (eg_hd->respond_rule) {
            /*
             * An HTTP::respond irule was triggered, so the http_respond
             * filter now owns generation of a response. Nothing for us to do
             * other than pass it along.
             */
            goto forward;
        }
    case HUDCTL_MESSAGE:
        if (msg == HUDCTL_MESSAGE) {
            DBG_ASSERT("JSON only supports SSE msg type on egress",
                    hud_ref_id_get(data) == HUD_MSG_ID_SSE);
            eg_json = ((struct sse_msg *)data)->ctx;
            ((struct sse_msg *)data)->ctx = NULL;
        } else {
            /* Retrieve & remove mime inst from the http_data in the message. */
            eg_mime = mime_multipart_addref(json_http_get_multipart(eg_hd));
            json_http_delete_multipart(eg_hd);
            scb->egress_is_multipart = (eg_mime != NULL);

            /* Retrieve & remove JSON cache from the http_data in the message. */
            eg_json = tmm_json_cache_addref(json_http_get_cache(eg_hd));
            json_http_delete_cache(eg_hd);
        }
        if (eg_json == NULL) {
            /* No json in egress. Pass through the whole req/resp/msg */
            goto forward;
        }
        scb->egress_is_json = TRUE;

        /* Have a JSON cache instance. Render it directly into xbuf. */
        err = tmm_json_cache_render_xbuf(eg_json, &scb->eg_rendered);
        tmm_json_cache_release(eg_json);
        eg_json = NULL;
        if (err == ERR_VERBOTEN) {
            /*
             * ERR_VERBOTEN = already rendered (perhaps by an iRule).
             * In this case, we won't abort the connection, but also won't
             * have any data in xb_out so will not egress anything.
             * Mark no egress so we don't forward the *_DONE message either.
             * With multipart there is egress (at least terminal boundary).
             */
            if (!scb->egress_is_multipart) {
                scb->f_send_egress = FALSE;
            }
            if (msg == HUDCTL_MESSAGE) {
                hud_ref_release(data);
            }
            goto out;
        }
        if (err != ERR_OK) {
            if (msg == HUDCTL_MESSAGE) {
                hud_ref_release(data);
            }
            goto abort;
        }

        /* If multipart, insert the JSON content into the first part. */
        if (scb->egress_is_multipart) {
            /* Insert the JSON content into the first part. */
            err = mime_multipart_part_insert_body_at(eg_mime, 1,
                    &scb->eg_rendered);
            /* ERR_MORE_DATA shouldn't happen as we have entire JSON part. */
            if (err != ERR_OK) {
                goto abort;
            }
            /* Render the JSON part which now contains the JSON content. */
            mime_multipart_render(eg_mime, &scb->eg_rendered);

            /* Update content length to add inserted json part */
            err = http_get_content_length(eg_hd, &content_len);
            if (err == ERR_OK) {
                err = http_content_length_update(eg_hd, content_len +
                        scb->eg_rendered.len);
                if (err != ERR_OK) {
                    goto abort;
                }
            } else if (err != ERR_NOT_FOUND) {
                goto abort;
            }
        } else if (msg != HUDCTL_MESSAGE) {
            /* JSON content might have changed due to iRules. */
            err = http_content_length_update(eg_hd, scb->eg_rendered.len);
            if (err != ERR_OK) {
                goto abort;
            }
        }

        /* Take temp because egressing msg is destructive to data. */
        is_sse = (hud_ref_id_get(data) == HUD_MSG_ID_SSE);

        /* Forward HUDCTL and any JSON part. Other egress will follow. */
        hud_orbit_handle_lower(node, msg, uf, data);

        if (is_sse) {
            /* For SSE, send json payload later when we see 'data' meta */
            scb->egress_is_json = FALSE;
        } else {
            hud_orbit_process_lower(node, uf, &scb->eg_rendered);
        }
        goto out;

    case HUDCTL_REQUEST_DONE:
    case HUDCTL_RESPONSE_DONE:
    case HUDCTL_MESSAGE_DONE:
        scb->egress_is_json = FALSE;
        scb->egress_is_multipart = FALSE;
        xbuf_free(&scb->eg_rendered);
        /* Only forward if we forwarded the REQUEST/RESPONSE/MSG before */
        if (scb->f_send_egress) {
            goto forward;
        }
        /* Dropping the current req/resp/msg... then normal egressing */
        scb->f_send_egress = TRUE;
        goto out;

    case HUDEVT_TCL:
        err = tclrule_continue_evt(node, uf, &rule_event);
        if (err == ERR_INPROGRESS) {
            goto out;
        }
        /*
         * ON an iRule failure, tclrule_continue_evt sends HUDEVT_ABORTED
         * then replaces internal ERR_TCL with ERR_OK which is returned here.
         * This check will probably never goto abort.
         */
        if (err != ERR_OK) {
            goto abort;
        }
        hud_orbit_unpause_ingress(node, uf);
        json_filter_handle_tcl_event_success(node, uf, rule_event, scb);
        goto out;

    case HUDCTL_PERFORM_METHOD:
        if (json_filter_handle_perform_method(node, uf, data)) {
            goto forward;
        }
        goto out;

    default:
        goto forward;
    }

forward:
    hud_orbit_handle_default(node, msg, uf, data);
    goto out;

abort:
    if (msg == HUDEVT_TCL) {
        JSON_IRULE_ERROR_LOG(CFSTR(uf), err,
                dynamic_tcl_get_event_name(rule_event, NULL));
    } else {
        JSON_INTERNAL_ERROR_LOG(CFSTR(uf), err);
    }
    hud_orbit_handle_upper(node, HUDEVT_ABORTED, uf,
            RST_WHY_ERR(uf, err, "JSON filter error"));

out:
    if (eg_mime != NULL) {
        mime_multipart_release(eg_mime);
    }
    return;
}

static err_t
hud_json_process_ingress(struct hudnode *node, union uflow *uf,
        struct xbuf *xb)
{
    struct json_scb *scb = HUDNODE_CTX(node);
    struct json_cfg *cfg = HUDNODE_PRIVATE(node);
    const char *part_type = NULL;
    err_t err = ERR_OK;
    char boundary[MIME_MAX_BOUNDARY_LEN + 1];
    unsigned len;
    UINT64 content_len;
    struct xbuf *tail_xb;
    struct hud_orb_entry *orb_entry;

    JSON_TRACEF(uf, "%d bytes", xb->len);
    if (scb->f_disabled || 
            (!scb->ingress_is_multipart && !scb->ingress_is_json) ||
            scb->f_json_finished) {
        /* Flow disabled or not JSON payload; forward immediately. */
        hud_orbit_process_upper(node, uf, xb);
        goto out;
    }

    if (scb->f_q_non_json_data) {
        /*
         * We are expecting some non-json chunk(s) of data which should be
         * queued for transmission once we release the req/msg.
         */

        /* First, check if we have capacity to buffer it */
        scb->non_json_bytes += xb->len;
        if (scb->non_json_bytes > cfg->max_non_json_bytes) {
            JSON_OTHER_CONTENT_TOOBIG_LOG(CFSTR(uf), scb->non_json_bytes,
                    cfg->max_non_json_bytes);
            err = json_filter_handle_json_error(node, scb, uf, xb);
            if (err != ERR_OK) {
                goto abort;
            }
            err = ERR_TOOBIG;
            goto out;
        }

        /* Is an xbuf already the tail of the q, that we can append to? */
        tail_xb = hud_orbit_queue_tail_xb(&scb->held_q);
        if (tail_xb != NULL) {
            xbuf_merge(tail_xb, xb);
            goto out;
        }
        /* Otherwise, create new queue entry for the xb and insert @ tail */
        orb_entry = hud_orbit_create_entry_xb(xb, 0);
        if (orb_entry == NULL) {
            err = ERR_MEM;
            goto abort;
        }
        hud_orbit_queue_insert_tail_entry(&scb->held_q, orb_entry);
        goto out;
    }

    /*
     * Accumulate the size of the payload as we get pieces of it, until we are
     * done with the JSON (if it's in a Mime multipart). JSON payload is kept
     * in the json cache but never forwarded to filter above. Check the size
     * against max_bytes and raise JSON_*_ERROR if exceeded.
     */
    scb->payload_bytes += xb->len;
    if (scb->payload_bytes > cfg->max_bytes) {
        JSON_CONTENT_TOOBIG_LOG(CFSTR(uf), scb->payload_bytes, cfg->max_bytes);
        err = json_filter_handle_json_error(node, scb, uf, xb);
        if (err != ERR_OK) {
            goto abort;
        }
        err = ERR_TOOBIG;
        goto out;
    }

    if (scb->ingress_is_multipart) {
        /* Mime Multipart. Get the boundary and initialize the MMP lib. */
        if (scb->mime == NULL) {
            /* Get first part and check if it's JSON. */
            len = mime_type_multipart_boundary(scb->http_cont_type,
                    boundary, MIME_MAX_BOUNDARY_LEN);
            if ((len == 0) || (len > MIME_MAX_BOUNDARY_LEN)) {
                JSON_MIME_INVALID_BOUNDARY_LOG(CFSTR(uf));
                err = ERR_ARG;
                goto out;
            }
            err = mime_multipart_create(&scb->mime, scb->http_cont_type,
                        boundary, cfg->mime_strict_crlf);
            if (err != ERR_OK) {
                goto abort;
            }
        }

        /* Consume all ingress to multipart buffer. */
        mime_multipart_consume(scb->mime, xb);

        /* Look for the JSON part, and when found initialize JSON parser. */
        if (!scb->ingress_is_json) {
            /* Check the Content-Type of the first part to see if it's JSON. */
            err = mime_multipart_part_type_at(scb->mime, 1, &part_type);
            if (err == ERR_MORE_DATA) {
                goto out;
            }
            if (err != ERR_OK) {
                goto abort;
            }
            if (strncasecmp(part_type, JSON_APPLICATION,
                    JSON_APPLICATION_LEN + 1) != 0) {
                JSON_NO_CONTENT_TYPE_LOG(CFSTR(uf));
                json_filter_handle_json_missing(node, scb, uf);
                goto out;
            }

            /* There is JSON in the first multipart. */
            scb->ingress_is_json = TRUE;
            err = json_filter_prepare_to_parse(scb, uf, cfg);
            if (err != ERR_OK) {
                goto abort;
            }
        }

        /* Extract available JSON content from the multipart for parsing. */
        err = mime_multipart_part_extract_body_at(scb->mime, 1, xb);
        if (err == ERR_MORE_DATA) {
            goto out;
        }
        if (err != ERR_OK) {
            goto abort;
        }
        scb->f_json_part_rcvd = TRUE;

        /* We got the whole part. Check for empty JSON part body. */
        if (xb->len == 0) {
            JSON_NO_CONTENT_LOG(CFSTR(uf));
            json_filter_handle_json_missing(node, scb, uf);
            goto out;
        }
    }

    /*
     * Here we drive the json parser incrementally. Passing this xbuf to the
     * json cache API appends all its content to the cache and parsing ensues
     * (or, if already parsed, parsing resumes using this additional payload).
     * We set f_valid_parse when we have fully parsed a valid JSON payload.
     */
    err = tmm_json_cache_parse_xbuf(scb->json, xb, NULL);
    if (err == ERR_OK) {
        /* We have the syntactic end of the JSON content. */
        scb->f_valid_parse = TRUE;

    } else if (err == ERR_MORE_DATA) {
        /* Parser wants more data ... */
        if (!scb->f_json_part_rcvd) {
            goto out;
        }
        /*
         * ... but there's no more in the multipart (JSON incomplete).
         * Try getting a valid parse by telling the parser that no more
         * data is coming. Regardless of success, continue through to
         * json_filter_handle_json_complete().
         */
        scb->f_valid_parse =
                (tmm_json_cache_parse_complete(scb->json) == ERR_OK);
        err = ERR_OK;

    } else {
        /* Parser failed due to error in content or exceeded token limit. */
        JSON_CONTENT_ERROR_LOG(CFSTR(uf), err);
        err = json_filter_handle_json_error(node, scb, uf, NULL);
        if (err != ERR_OK) {
            goto abort;
        }
        goto out;
    }

    /*
     * At this point, there is no more JSON data coming.
     * XXX: Stop driving parser with more ingress after this. Sink it?
     *  Note: This behaviour existed before the Mime multipart support.
     */

    if (scb->ingress_is_multipart) {
        /*
         * The entire JSON part body has been consumed into the JSON cache, so
         * the multipart buffer contains a JSON multipart with headers only.
         * Push back remaining ingress (beyond JSON part) all the way to
         * orbits so we can forward it after the JSON_REQUEST/JSON_RESPONSE
         * iRule event, along with the message which contains the multipart
         * instance. The receiving end will find the JSON part in the Mime
         * Multipart instance attached to the http_data with the message,
         * and any subsequent parts and the terminal boundary will come with
         * the egress.
         * XXX: Not good to buffer entire JSON content. But we did before!
         */
        mime_multipart_unconsume_after(scb->mime, 1, xb);
        if (xb->len != 0) {
            scb->payload_bytes -= xb->len;
            hud_orbit_pushback_ingress(node, uf, xb);
            hud_orbit_unpause_ingress(node, uf);
        }
        scb->f_json_finished = TRUE;

        /* Update http content length to subtract buffered json part */
        err = http_get_content_length(scb->http, &content_len);
        if (err == ERR_OK) {
            err = http_content_length_update(scb->http,
                    content_len - scb->payload_bytes);
            if (err != ERR_OK) {
                goto abort;
            }
        } else if (err != ERR_NOT_FOUND) {
            goto abort;
        }

        /*
         * Check results, attach JSON cache and mime multipart instance to
         * http_data, and raise events.
         */
        err = json_filter_handle_json_complete(node, scb, uf);
        if (err != ERR_OK) {
            goto abort; /* Internal error. */
        }
        goto out;
    }
    goto out;

abort:
    JSON_INTERNAL_ERROR_LOG(CFSTR(uf), err);
    hud_orbit_handle_upper(node, HUDEVT_ABORTED, uf,
            RST_WHY_ERR(uf, err, "JSON filter error"));

out:
    return err;
}

static err_t
hud_json_process_egress(struct hudnode *node, union uflow *uf,
        struct xbuf *xb)
{
    struct json_scb *scb = HUDNODE_CTX(node);
    err_t err = ERR_OK;

    JSON_TRACEF(uf, "%d bytes", xb->len);

    /* JSON single part should not receive egress for JSON. Drop any. */
    if (!scb->f_disabled && !scb->egress_is_multipart && 
            scb->egress_is_json) {
        xbuf_free(xb);
        goto out;
    }

    hud_orbit_process_lower(node, uf, xb);

out:
    return err;
}

/*
 * JSON hudfilter template
 */

HUD_DEFAULT_HANDLER_DECLARE(json_filter, (hud_handler)hud_json_handler);
static const struct hudfilter_spec hudfilter_json_spec = {
    .name = "JSON",
    .f_clientside = TRUE,
    .f_serverside = TRUE,
    .f_orbit = TRUE,
    .scb_sz = sizeof(struct json_scb),
    .pcb_sz = sizeof(struct json_scb),
    .private_sz = sizeof(struct json_cfg),
    .init = hud_json_init,
    .uninit = hud_json_uninit,
    .handler = HUD_DEFAULT_HANDLER(json_filter),
    .s_ingress = hud_json_process_ingress,
    .s_egress = hud_json_process_egress,
    .clientside_position = HUDFILTER_POS_CLIENT_JSON,
    .serverside_position = HUDFILTER_POS_SERVER_JSON,
};
HUD_POPULATE_FILTER(hudfilter_json, hudfilter_json_spec);
HUD_TYPEID_DECLARE(HUD_FILTER, "JSON", hudfilter_json, HA_ID_HA_NOT_USED);

