/*
 * This is the size of struct hud_orbit, and must be
 * a multiple of the cacheline size to keep the pcb
 * of hudnodes well aligned.
 */
#define HUD_ORBIT_SIZE 64

/*
 * Fixed granularity for per-connflow memory-unit (MU) accounting.
 * One MU represents ORB_MU_SIZE bytes of buffered egress data.  The
 * value is intentionally independent of any per-listener or per-flow
 * watermark setting so that MU counts are comparable across all TMM
 * flows.
 *
 * A MU delta is reported whenever egress_len crosses an 8 KiB boundary
 * (i.e. floor(egress_len / ORB_MU_SIZE) changes).
 */
#define ORB_MU_SIZE 8192

/* Orbits internal flags, exposed for optimization purposes */
#define ORB_FG_EXISTS_INGRESS           0x00000001
#define ORB_FG_EXISTS_INGRESS_OUT       0x00000002
#define ORB_FG_EXISTS_EGRESS            0x00000004
#define ORB_FG_EXISTS_EGRESS_OUT        0x00000008
#define ORB_FG_ACCEPTED                 0x00000010
#define ORB_FG_INSERT                   0x00000020
#define ORB_FG_CALLBACK                 0x00000040
#define ORB_FG_SENT                     0x00000080
#define ORB_FG_PAUSE_INGRESS            0x00000100
#define ORB_FG_PAUSE_INGRESS_OUT        0x00000200
#define ORB_FG_PAUSE_EGRESS             0x00000400
#define ORB_FG_PAUSE_EGRESS_OUT         0x00000800
#define ORB_FG_PASSTHRU_UP              0x00001000
#define ORB_FG_PASSTHRU_DOWN            0x00002000
#define ORB_FG_XOFF_ABOVE               0x00004000
#define ORB_FG_XOFF_BELOW               0x00008000
#define ORB_FG_DROP_INGRESS             0x00010000
#define ORB_FG_DROP_EGRESS              0x00020000
#define ORB_FG_COMPLETE                 0x00040000
#define ORB_FG_FREE                     0x00080000
#define ORB_FG_FLUSHING                 0x00100000
#define ORB_FG_QUEUE_ALTERED            0x00200000
#define ORB_FG_PEER_XOFF                0x00400000
#define ORB_FG_BLOCKED_DOWN             0x00800000

#define ORB_FG_PACKET                   0x01000000
#define ORB_FG_HOLD_ACCEPTED            0x02000000
#define ORB_FG_NOTIFY_SENT              0x04000000
#define ORB_FG_NOTIFY_XOFF              0x08000000
#define ORB_FG_DROP_XOFF_ABOVE          0x10000000
#define ORB_FG_HAIRPIN                  0x20000000
#define ORB_FG_UNUSED3                  0x40000000
#define ORB_FG_UNUSED4                  0x80000000

#define ORB_STATE_UP        0x01
#define ORB_STATE_DOWN      0x02
#define ORB_STATE_INIT      0x04
#define ORB_STATE_SLOW      0x08

extern RTTHREAD UINT64 hud_orbit_state;

struct hud_orb_entry;
SIMPLEQ_HEAD(hud_orb_queue, hud_orb_entry);

/* Internal functions for orbit framework */
void hud_orbit_init(struct hudnode *node, hud_handler handler);
void hud_orbit_stream_init(struct hudnode *node, struct hudnode *pnode);

/*
 * Hud Orbit Queue API.
 *
 * This allows buffering messages and data.
 * This currently is a SIMPLEQ under the hood.
 */

/* Initialize a queue */
static inline void
hud_orbit_queue_init(struct hud_orb_queue *q)
{
    SIMPLEQ_INIT(q);
}

/* Is a queue empty? */
static inline BOOL
hud_orbit_queue_empty(struct hud_orb_queue *q)
{
    return SIMPLEQ_EMPTY(q);
}

/* SIMPLEQ_FOREACH, with a hidden type */
#define HUD_ORBIT_QUEUE_FOREACH(var, queue)                             \
    for ((var) = ((queue)->sqh_first);                                  \
         (var);                                                         \
