void hud_orbit_handle_async_above(struct hudnode *node, hud_msg_t msg,
        union uflow *uf, void *data);

static inline UINT32
hud_orbit_internal_flag_get(struct hudnode *node)
{
    return ((UINT32 *)node)[-1];
}

static inline BOOL
hud_orbit_state_mismatch(struct hudnode *node, UINT8 dirn)
{
    /*
     * If the node doesn't match, or the specified direction bit is not set
     * return TRUE
     *
     * This works because hud_orbit_state contains the node in the top bits,
     * and the direction in the bottom four bits.
     *
     * (INT(node) + dirn) sets the matching pattern.
     * xoring with hud_orbit_state will result in zero if everything
     * is as expected.  However... there may be some low bits set that
     * we don't care about.  We want to ignore the other bits in the low
     * nybble, but not our direction bit.  (dirn - 16) constructs the
     * correct mask for this.
     */
    return (((INT(node) + dirn) ^ hud_orbit_state) & (dirn - 16ull)) != 0;
}

/*
 * Message Passing
 */

static inline void
hud_orbit_handle_lower(struct hudnode *node, hud_msg_t msg, union uflow *uf,
        void *data)
{
    if (IS_HUDEVT_MSG(msg)) {
        OOPS("Expected HUDCTL!\n");
    } else if (IS_HUDCTL_SYNC_MSG(msg)) {
        if ((msg == HUDCTL_ABORT) || (msg == HUDCTL_TEARDOWN)) {
            hud_orbit_handle_teardown_lower(node, msg, uf, data);
        } else {
            uflow_handle_lower(node, msg, uf, data);
        }
    } else {
        if ((msg == HUDCTL_SHUTDOWN) || (msg == HUDCTL_EGRESS_ABORT) ||
                (hud_orbit_internal_flag_get(node) &
                  (ORB_FG_PAUSE_EGRESS_OUT | ORB_FG_DROP_EGRESS |
                   ORB_FG_EXISTS_EGRESS_OUT | ORB_FG_FREE | ORB_FG_CALLBACK)) ||
                hud_orbit_state_mismatch(node, ORB_STATE_DOWN)) {
            hud_orbit_handle_async_below(node, msg, uf, data);
        } else {
            uflow_handle_lower(node, msg, uf, data);
        }
    }
}

static inline void
hud_orbit_handle_upper(struct hudnode *node, hud_msg_t msg, union uflow *uf,
        void *data)
{
    if (IS_HUDCTL_MSG(msg)) {
        OOPS("Expected HUDEVT!\n");
    } else if (IS_HUDEVT_DIRECT_MSG(msg)) {
        OOPS("Unexpected HUDEVT leaks from a filter!\n");
    } else if (IS_HUDEVT_SYNC_MSG(msg)){
        if ((msg == HUDEVT_ABORTED) || (msg == HUDEVT_EXPIRED)) {
            hud_orbit_handle_abort_above(node, msg, uf, data);
        } else if (msg == HUDEVT_SENT) {
            hud_orbit_unpause(node, uf);
        } else {
            uflow_handle_upper(node, msg, uf, data);
        }
    } else {
        if ((msg == HUDEVT_SHUTDOWN) || (msg == HUDEVT_EOF) ||
                (msg == HUDEVT_INGRESS_ABORT) ||
                unlikely((hud_orbit_internal_flag_get(node) &
                        (ORB_FG_PAUSE_INGRESS_OUT | ORB_FG_DROP_INGRESS |
                         ORB_FG_FREE | ORB_FG_EXISTS_INGRESS_OUT |
                         ORB_FG_CALLBACK | ORB_FG_ACCEPTED)) ||
                    hud_orbit_state_mismatch(node, ORB_STATE_UP))) {
            hud_orbit_handle_async_above(node, msg, uf, data);
        } else {
            uflow_handle_upper(node, msg, uf, data);
        }
    }
}

static inline void
hud_orbit_handle_default(struct hudnode *node, hud_msg_t msg, union uflow *uf,
        void *data)
{
    if (IS_HUDCTL_MSG(msg)) {
        hud_orbit_handle_lower(node, msg, uf, data);
    } else {
        hud_orbit_handle_upper(node, msg, uf, data);
    }
}

static inline void
hud_orbit_handle_stream(struct hudnode *node, hud_msg_t msg, union uflow *uf,
        void *data)
{
    if (IS_HUDCTL_MSG(msg)) {
        OOPS("Expected HUDEVT!\n");
    } else if (IS_HUDEVT_DIRECT_MSG(msg)) {
        OOPS("Unexpected HUDEVT leaks from a filter!\n");
    } else if (IS_HUDEVT_SYNC_MSG(msg)){
        if ((msg == HUDEVT_ABORTED) || (msg == HUDEVT_EXPIRED)) {
            hud_orbit_handle_abort_above(node, msg, uf, data);
        } else if (msg == HUDEVT_SENT) {
            hud_orbit_unpause(node, uf);
        } else {
            uflow_handle_upper(node, msg, uf, data);
        }
    } else {
        if ((msg == HUDEVT_SHUTDOWN) || (msg == HUDEVT_EOF) ||
                (msg == HUDEVT_INGRESS_ABORT) ||
                unlikely((hud_orbit_internal_flag_get(node) &
                        (ORB_FG_PAUSE_INGRESS_OUT | ORB_FG_DROP_INGRESS |
                         ORB_FG_FREE | ORB_FG_EXISTS_INGRESS_OUT |
                         ORB_FG_CALLBACK | ORB_FG_ACCEPTED)) ||
                    hud_orbit_state_mismatch(HUDNODE_NODE(node->parent),
                         ORB_STATE_UP))) {
            hud_orbit_handle_async_above(node, msg, uf, data);
